INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prinzessin-lillifee---meine-liebsten-freunde-europe-ende', 'NDS', 'Prinzessin Lillifee - Meine Liebsten Freunde (Europe) (En,De)', '2010', 'Adventure', 'Flashpoint', '1', 'Adventure', 'Social & Mini-games.', 'Play with your best friends in a magical world.', 'Friendship-focused mini-game collection.', 'Meine Liebsten Freunde (Europe) focuses on social interaction. Join Lillifee and her animal friends in various activities like baking, dancing, and dressing up in this cozy German-developed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prinzessin-lillifee---meine-wunderbare-welt-germany-ende', 'NDS', 'Prinzessin Lillifee - Meine Wunderbare Welt (Germany) (En,De)', '2011', 'Adventure', 'Flashpoint', '1', 'Adventure', 'Creativity & Simulation.', 'Explore Lillifee''s world and create your own stories.', 'Creative sandbox game for younger players.', 'Meine Wunderbare Welt (Germany) offers a digital dollhouse experience. Decorate rooms, dress up characters, and explore various locations in the fairy kingdom at your own pace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prinzessin-lillifee-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'Prinzessin Lillifee Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Flashpoint', '1', 'Puzzle', 'Jigsaw Puzzle.', 'Complete beautiful puzzles featuring Lillifee.', 'Relaxing puzzle collection for the European market.', 'Prinzessin Lillifee Puzzle features dozens of high-quality illustrations. With adjustable difficulty and simple touch controls, it’s an ideal "pick-up-and-play" game for young puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prism---light-the-way-europe-enfrdeesit', 'NDS', 'Prism - Light the Way (Europe) (En,Fr,De,Es,It)', '2006', 'Puzzle', 'Nocturnal', '1', 'Puzzle', 'Logic Puzzle.', 'Solve light-based puzzles by reflecting beams.', 'Innovative light-refraction puzzle game.', 'Prism: Light the Way (Europe) challenges your brain. Arrange mirrors, lenses, and prisms to guide colored light beams to their targets in over 100 increasingly complex levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prism---light-the-way-usa-enfrdeesit', 'NDS', 'Prism - Light the Way (USA) (En,Fr,De,Es,It)', '2006', 'Puzzle', 'Nocturnal', '1', 'Puzzle', 'Logic Puzzle.', 'Solve light-based puzzles by reflecting beams.', 'North American release of the light-refraction puzzler.', 'Think strategically in Prism: Light the Way (USA). With its glowing aesthetic and clever mechanics, it’s a unique logic game that tests your spatial reasoning and color-mixing skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-evolution-soccer-2008-europe-enfrdeesit', 'NDS', 'Pro Evolution Soccer 2008 (Europe) (En,Fr,De,Es,It)', '2007', 'Sports', 'Konami', '2', 'Soccer', 'Soccer / Sports.', 'Lead your favorite team to victory in the league.', 'Portable version of the 2008 soccer hit.', 'PES 2008 (Europe) features the "World Tour" mode and improved touch-screen controls. Manage your squad, execute precise passes, and score epic goals in this multi-language soccer sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-evolution-soccer-2008-usa-enes', 'NDS', 'Pro Evolution Soccer 2008 (USA) (En,Es)', '2007', 'Sports', 'Konami', '2', 'Soccer', 'Soccer / Sports.', 'Lead your favorite team to victory in the league.', 'North American release of PES 2008.', 'Experience the intensity of Pro Evolution Soccer 2008 (USA). With licensed teams and realistic player movements, it brings the definitive soccer experience to the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-evolution-soccer-6-europe-enfrdeesit-rev-1', 'NDS', 'Pro Evolution Soccer 6 (Europe) (En,Fr,De,Es,It) (Rev 1)', '2006', 'Sports', 'Konami', '2', 'Soccer', 'Soccer / Sports.', 'Compete in international tournaments and leagues.', 'Classic PES gameplay with refined mechanics.', 'PES 6 (Europe) Rev 1 is the polished version of the fan-favorite soccer game. Featuring smooth animations and deep tactical options, it remains a gold standard for handheld sports titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-famista-ds-japan', 'NDS', 'Pro Yakyuu Famista DS (Japan)', '2006', 'Sports', 'Namco', '1', 'Baseball', 'Baseball / Sports.', 'Win the Japanese baseball championship.', 'First entry of the Famista series for the DS.', 'Pro Yakyuu Famista DS (Japan) brings the classic Namco arcade baseball feel to the handheld. Feature realistic players and easy-to-learn controls for fast-paced, fun baseball matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-famista-ds-2009-japan', 'NDS', 'Pro Yakyuu Famista DS 2009 (Japan)', '2009', 'Sports', 'Namco', '1', 'Baseball', 'Baseball / Sports.', 'Compete in the 2009 Japanese baseball season.', 'Updated baseball simulation for Japan.', 'Famista DS 2009 features updated rosters and improved graphics. Participate in the full season or enjoy quick exhibition matches with your favorite Japanese baseball teams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-famista-ds-2010-japan', 'NDS', 'Pro Yakyuu Famista DS 2010 (Japan)', '2010', 'Sports', 'Namco', '1', 'Baseball', 'Baseball / Sports.', 'Master the 2010 baseball season and build a team.', 'Final 2010 edition of the Famista DS series.', 'Pro Yakyuu Famista DS 2010 (Japan) includes new player data and refined "My Player" modes, allowing you to create and train your own baseball legend in this comprehensive sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-team-o-tsukurou!-japan', 'NDS', 'Pro Yakyuu Team o Tsukurou! (Japan)', '2005', 'Simulation', 'Sega', '1', 'Team Management', 'Baseball / Management.', 'Manage a professional baseball team to success.', 'Deep baseball management simulator from SEGA.', 'Pro Yakyuu Team o Tsukurou! (Japan) puts you in the manager''s seat. Scout talent, set training regimens, and handle finances to build a dynasty in the world of Japanese baseball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-team-o-tsukurou!-2-japan', 'NDS', 'Pro Yakyuu Team o Tsukurou! 2 (Japan)', '2006', 'Simulation', 'Sega', '1', 'Team Management', 'Baseball / Management.', 'Expand your baseball empire and win the title.', 'Sequel to the popular management simulator.', 'Pro Yakyuu Team o Tsukurou! 2 (Japan) adds more depth to the front-office experience. Negotiate contracts and watch your strategies play out on the field in this detailed SEGA simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prof-di-parole-il-italy', 'NDS', 'Prof di Parole, Il (Italy)', '2007', 'Educational', 'Artematica', '1', 'Language Learning', 'Educational / Language.', 'Improve your vocabulary through Italian word games.', 'Word-focused brain training for Italian speakers.', 'Il Prof di Parole (Italy) offers a variety of linguistic challenges. Solve crosswords, word searches, and anagrams to improve your Italian vocabulary and mental agility in a fun way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('profesor-layton-y-el-futuro-perdido-el-spain', 'NDS', 'Profesor Layton y el Futuro Perdido, El (Spain)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'Spanish version of The Unwound Future.', 'El Profesor Layton y el Futuro Perdido (Spain) cierra la trilogía original. Resuelve más de 165 acertijos mientras exploras un Londres futurista y descubres la historia más emotiva de la saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('profesor-layton-y-la-caja-de-pandora-el-spain', 'NDS', 'Profesor Layton y la Caja de Pandora, El (Spain)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'Spanish version of The Diabolical Box.', 'El Profesor Layton y la Caja de Pandora (Spain) te lleva en un viaje a bordo del Molentary Express. Investiga la leyenda de una caja que mata a quien la abre a través de ingeniosos puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professeur-layton-et-la-boite-de-pandore-france', 'NDS', 'Professeur Layton et la Boite de Pandore (France)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'French version of Pandora''s Box.', 'Professeur Layton et la Boite de Pandore (France) propose une aventure riche en mystères. Interrogez les suspects et résolvez des énigmes logiques pour lever le voile sur le secret de la boîte.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professeur-layton-et-le-destin-perdu-france', 'NDS', 'Professeur Layton et le Destin Perdu (France)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'French version of the Lost Future.', 'Professeur Layton et le Destin Perdu (France) emmène Layton et Luke dans le temps. Une aventure épique avec des cinématiques animées et des puzzles qui mettront votre logique à l''épreuve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professional-fishermans-tour---northern-hemisphere-usa', 'NDS', 'Professional Fisherman''s Tour - Northern Hemisphere (USA)', '2006', 'Sports', 'Aksys Games', '4', 'Fishing', 'Sports / Fishing.', 'Catch record-breaking fish across the Northern Hemisphere.', 'Realistic fishing simulation for the USA.', 'Professional Fisherman''s Tour (USA) features authentic gear and diverse locations. Master the casting and reeling mechanics with the stylus to land the biggest bass and trout in high-stakes tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-brainiums-games-usa', 'NDS', 'Professor Brainium''s Games (USA)', '2008', 'Puzzle', 'Smart Bomb', '1', 'Brain Training', 'Puzzle / Brain Training.', 'Improve cognitive skills with various mini-games.', 'Collection of daily mental exercises for USA.', 'Professor Brainium''s Games offers a laboratory of puzzles. Track your progress in memory, math, and perception tests designed to keep your brain sharp through quick, daily gaming sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-brainmaniac-europe-enfrdeesit', 'NDS', 'Professor Brainmaniac (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Asylum Entertainment', '1', 'Brain Training', 'Puzzle / Brain Training.', 'Complete daily challenges to boost brain power.', 'European brain training and logic collection.', 'Professor Brainmaniac (Europe) features a variety of logic and observation games. Compete against the professor''s clock and improve your mental age in this multi-language brain trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-heinz-wolffs-gravity-europe-enfrdeesit', 'NDS', 'Professor Heinz Wolff''s Gravity (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Four Head Studios', '1', 'Physics Puzzle', 'Physics Puzzle.', 'Use gravity and tools to guide a spark to the goal.', 'Physics-based puzzle game with real-world logic.', 'Professor Heinz Wolff''s Gravity (Europe) features 100 levels of mechanical challenges. Place blocks, ramps, and levers to create a chain reaction that completes each experimental stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-heinz-wolffs-gravity-usa-enfrdeesit', 'NDS', 'Professor Heinz Wolff''s Gravity (USA) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Four Head Studios', '1', 'Physics Puzzle', 'Physics Puzzle.', 'Use gravity and tools to guide a spark to the goal.', 'North American release of the physics puzzler.', 'Put your engineering skills to the test in Professor Heinz Wolff''s Gravity (USA). Utilize various gadgets to solve complex physics puzzles endorsed by the famous scientist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-kageyamas-maths-training---the-hundred-cell-calculation-method-europe-enfrdeesit', 'NDS', 'Professor Kageyama''s Maths Training - The Hundred Cell Calculation Method (Europe) (En,Fr,De,Es,It)', '2007', 'Educational', 'Namco', '1', 'Math Training', 'Educational / Math.', 'Master mental math using high-speed calculation.', 'Rapid-fire math trainer for Europe.', 'Professor Kageyama''s Maths Training uses the famous Hundred Cell Method. Improve your calculation speed and accuracy with daily drills that have helped millions of students in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-pandoras-box-europe', 'NDS', 'Professor Layton and Pandora''s Box (Europe)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'European English release of Pandora''s Box.', 'Professor Layton and Pandora''s Box (Europe) continues the journey. Solve riddles, brew tea, and interact with a cast of eccentric characters while solving a supernatural mystery across Europe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-the-curious-village-europe-enfrdeesit', 'NDS', 'Professor Layton and the Curious Village (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of the Golden Apple in St. Mystere.', 'The legendary first game of the series (Europe).', 'Professor Layton and the Curious Village (Europe) introduces the world of puzzles. Join Layton and Luke as they investigate a wealthy village where every inhabitant has a riddle to share.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-the-curious-village-usa', 'NDS', 'Professor Layton and the Curious Village (USA)', '2007', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of the Golden Apple in St. Mystere.', 'North American release of the first Layton game.', 'Experience the start of the phenomenon in The Curious Village (USA). Master touch-screen puzzles and enjoy a charming story inspired by classic detective literature and European art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-the-diabolical-box-usa', 'NDS', 'Professor Layton and the Diabolical Box (USA)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'North American release of the second Layton title.', 'Professor Layton and the Diabolical Box (USA) takes the duo on a train journey. Featuring improved animation and over 150 new brain-teasers, it’s a high point for the handheld series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-the-lost-future-europe', 'NDS', 'Professor Layton and the Lost Future (Europe)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'European English release of the third Layton title.', 'Professor Layton and the Lost Future (Europe) is the series'' most ambitious entry. Help Luke save his future self in a sprawling narrative filled with time-travel and deep emotional stakes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-and-the-unwound-future-usa', 'NDS', 'Professor Layton and the Unwound Future (USA)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'North American version of the third Layton game.', 'Professor Layton and the Unwound Future (USA) features a gripping finale to the original trilogy. Explore the streets of London and solve the Professor''s most challenging puzzles to date.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-e-il-futuro-perduto-il-italy', 'NDS', 'Professor Layton e il Futuro Perduto, Il (Italy)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'Italian version of the Unwound Future.', 'Il Futuro Perduto (Italy) porta la magia di Layton in italiano. Risolvi oltre 165 enigmi logici in questa epica conclusione della trilogia, tra viaggi nel tempo e misteri mozzafiato.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-e-lo-scrigno-di-pandora-il-italy', 'NDS', 'Professor Layton e lo Scrigno di Pandora, Il (Italy)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'Italian version of the Diabolical Box.', 'Lo Scrigno di Pandora (Italy) ti invita a un misterioso viaggio in treno. Risolvi gli enigmi per scoprire la verità sulla leggendaria scatola che si dice porti alla morte.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-en-de-doos-van-pandora-netherlands', 'NDS', 'Professor Layton en de Doos van Pandora (Netherlands)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'Dutch version of Pandora''s Box.', 'Professor Layton en de Doos van Pandora (Netherlands) biedt een meeslepend mysterie. Los de puzzels op en ontdek het geheim van de legendarische doos in deze volledig gelokaliseerde versie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-en-de-verloren-toekomst-netherlands', 'NDS', 'Professor Layton en de Verloren Toekomst (Netherlands)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'Dutch version of the Lost Future.', 'In De Verloren Toekomst (Netherlands) reizen Layton en Luke naar een toekomstig Londen. Geniet van de prachtige animaties en uitdagende breinbrekers in dit emotionele avontuur.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-und-die-schatulle-der-pandora-germany', 'NDS', 'Professor Layton und die Schatulle der Pandora (Germany)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Uncover the truth behind the Elysian Box and its curse.', 'German version of the Diabolical Box.', 'Professor Layton und die Schatulle der Pandora (Germany) lässt dich den rätselhaften Tod von Laytons Mentor untersuchen. Knoble dich durch über 150 Rätsel im luxuriösen Molentary Express.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professor-layton-und-die-verlorene-zukunft-germany', 'NDS', 'Professor Layton und die Verlorene Zukunft (Germany)', '2010', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle / Adventure.', 'Solve the mystery of a future London and stop a tragedy.', 'German version of the Lost Future.', 'Die Verlorene Zukunft (Germany) ist das packende Finale der ersten Trilogie. Begleite Professor Layton und Luke auf ihrer wichtigsten Mission, um das Schicksal Londons zu retten.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professors-brain-trainer-the---logic-europe-enfrit', 'NDS', 'Professor''s Brain Trainer, The - Logic (Europe) (En,Fr,It)', '2008', 'Educational', 'Namco', '1', 'Logic Training', 'Puzzle / Brain Training.', 'Sharpen your logical reasoning with daily exercises.', 'Logic-focused brain trainer for Europe.', 'The Professor''s Brain Trainer: Logic focuses on spatial reasoning and deductions. Track your mental improvement through targeted mini-games and logical challenges in three languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professors-brain-trainer-the---memory-europe-enfrit', 'NDS', 'Professor''s Brain Trainer, The - Memory (Europe) (En,Fr,It)', '2008', 'Educational', 'Namco', '1', 'Memory Training', 'Puzzle / Brain Training.', 'Boost your memory and recall speed.', 'Memory-focused brain trainer for Europe.', 'The Professor''s Brain Trainer: Memory uses interactive drills to expand your short-term and long-term recall. Perfect for quick sessions to keep your mind active and healthy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('project-hacker---kakusei-japan', 'NDS', 'Project Hacker - Kakusei (Japan)', '2010', 'Adventure', 'Red Entertainment', '1', 'Action Adventure', 'Adventure / Visual Novel.', 'Use hacking and investigation skills to solve cases.', 'Tech-focused mystery adventure for Japan.', 'Project Hacker: Kakusei (Japan) puts you in the role of a computer security agent. Use the touch screen to bypass firewalls and analyze data in this unique futuristic detective story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('project-rub-europe-enjafrdeesit', 'NDS', 'Project Rub (Europe) (En,Ja,Fr,De,Es,It)', '2006', 'Action', 'Sega', '1', 'Experimental Action', 'Mini-game / Lifestyle.', 'Complete bizarre challenges to win over a girl.', 'Experimental and stylish mini-game collection.', 'Project Rub (Europe) is a cult classic that uses every DS feature. Blow into the mic, rub the screen, and tap rhythmically to impress your love interest in this visually striking game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prova-del-cuoco-la-italy', 'NDS', 'Prova del Cuoco, La (Italy)', '2008', 'Simulation', 'Rai Trade', '1', 'Cooking Simulation', 'Cooking / Simulation.', 'Compete in a professional cooking game show.', 'Italian cooking simulation based on the TV show.', 'La Prova del Cuoco (Italy) lets you step into the kitchen of the famous TV program. Follow recipes, manage ingredients, and satisfy the judges to become the ultimate virtual chef.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pucca---power-up-europe-enfrdeesit', 'NDS', 'Pucca - Power Up (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Climax Studios', '1', 'Platformer', 'Action Platformer.', 'Defeat enemies and win the heart of Garu.', 'Colorful action game based on the Pucca series.', 'Pucca: Power Up (Europe) features fast-paced platforming. Control Pucca as she chases Garu through various environments, utilizing powerful moves and quirky gadgets in this multi-language hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pucca---power-up-korea', 'NDS', 'Pucca - Power Up (Korea)', '2009', 'Action', 'Climax Studios', '1', 'Platformer', 'Action Platformer.', 'Defeat enemies and win the heart of Garu.', 'Original Korean version of the Pucca adventure.', 'Experience the high-energy world of Pucca in her home country. Pucca: Power Up (Korea) features the iconic art style and frantic gameplay that made the franchise a global phenomenon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pucca---power-up-usa', 'NDS', 'Pucca - Power Up (USA)', '2009', 'Action', 'Climax Studios', '1', 'Platformer', 'Action Platformer.', 'Defeat enemies and win the heart of Garu.', 'North American release of the Pucca platformer.', 'Pucca: Power Up (USA) brings the beloved character to North America. Battle ninjas, explore the village, and enjoy hilarious cutscenes in this polished and fun action title for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puchi-puchi-virus-japan', 'NDS', 'Puchi Puchi Virus (Japan)', '2006', 'Puzzle', 'Jaleco', '2', 'Arcade Puzzle', 'Match-3 Puzzle.', 'Clear viruses by linking cells of the same color.', 'Quirky and colorful medical puzzle for Japan.', 'Puchi Puchi Virus (Japan) is an addictive puzzle game where you link virus cells to pop them. Featuring a bizarre cast of characters and fast-paced gameplay, it''s a unique take on the match-3 genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puchi-puchi-virus-usa', 'NDS', 'Puchi Puchi Virus (USA)', '2006', 'Puzzle', 'Jaleco', '2', 'Arcade Puzzle', 'Match-3 Puzzle.', 'Clear viruses by linking cells of the same color.', 'North American release of the virus-popping puzzler.', 'Save the patients in Puchi Puchi Virus (USA). Use the stylus to create chains of viruses and trigger massive combos. It’s a fast, frantic, and funny logic game that rewards quick thinking and precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puffins---island-adventure-usa-enfr', 'NDS', 'Puffins - Island Adventure (USA) (En,Fr)', '2011', 'Adventure', 'Other Ocean Interactive', '1', 'Family Adventure', 'Life simulation & Mini-games.', 'Live the life of a puffin and raise a family.', 'Nature-themed adventure on a remote island.', 'Puffins: Island Adventure (USA) lets you experience life as a puffin. Compete in 10 diverse mini-games based on real puffin behavior, like diving for fish and racing, to protect your colony and hatch your eggs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puppy-luv---spa-and-resort-europe', 'NDS', 'Puppy Luv - Spa and Resort (Europe)', '2008', 'Simulation', 'Spike', '1', 'Pet Care', 'Pet Spa Simulation.', 'Manage a luxury resort for pampered puppies.', 'Canine wellness and styling simulation for Europe.', 'Puppy Luv: Spa and Resort (Europe) tasks you with grooming and relaxing your furry clients. Use the touch screen to give massages, baths, and stylish makeovers to the town''s cutest dogs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puppy-luv---spa-and-resort-europe-fresit', 'NDS', 'Puppy Luv - Spa and Resort (Europe) (Fr,Es,It)', '2008', 'Simulation', 'Spike', '1', 'Pet Care', 'Pet Spa Simulation.', 'Manage a luxury resort for pampered puppies.', 'Multi-language edition of the puppy spa game.', 'Pamper puppies in French, Spanish, or Italian. This version of the spa simulation offers a wide range of accessories and treatments to keep your virtual clients happy and wagging their tails.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puppy-luv---spa-and-resort-usa', 'NDS', 'Puppy Luv - Spa and Resort (USA)', '2008', 'Simulation', 'Spike', '1', 'Pet Care', 'Pet Spa Simulation.', 'Manage a luxury resort for pampered puppies.', 'North American release of the puppy resort sim.', 'Become the ultimate dog groomer in Puppy Luv: Spa and Resort (USA). Unlock new treatments and luxury items as you expand your business and provide top-tier care for every pup that enters your spa.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puppy-palace-usa-enfres', 'NDS', 'Puppy Palace (USA) (En,Fr,Es)', '2009', 'Simulation', 'Ubisoft', '1', 'Pet Management', 'Pet Simulation.', 'Care for puppies and find them the perfect home.', 'Heartwarming dog adoption and care simulation.', 'Puppy Palace (USA) lets you run a puppy foster home. Train, feed, and play with different breeds using the stylus, ensuring they are happy and healthy enough to be adopted by a loving family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('purr-pals-europe-enesit', 'NDS', 'Purr Pals (Europe) (En,Es,It)', '2007', 'Simulation', 'OGR Games', '1', 'Pet Simulation', 'Cat Simulation.', 'Adopt and raise your favorite breed of kitten.', 'Realistic feline care and bonding simulator.', 'Purr Pals (Europe) features 40 breeds of kittens to choose from. Use the touch screen to pet and groom them, and the microphone to call them, creating a lifelike bond with your virtual pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('purr-pals-europe-enfrde', 'NDS', 'Purr Pals (Europe) (En,Fr,De)', '2007', 'Simulation', 'OGR Games', '1', 'Pet Simulation', 'Cat Simulation.', 'Adopt and raise your favorite breed of kitten.', 'English, French, and German release of Purr Pals.', 'Customize your kitten''s environment and personality in this European edition. Play fun mini-games with your cat to earn coins for new toys, furniture, and adorable accessories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('purr-pals-usa', 'NDS', 'Purr Pals (USA)', '2007', 'Simulation', 'OGR Games', '1', 'Pet Simulation', 'Cat Simulation.', 'Adopt and raise your favorite breed of kitten.', 'North American release of the popular cat sim.', 'Purr Pals (USA) is the ultimate digital cat experience. Featuring realistic AI and thousands of customization options, it’s the perfect game for cat lovers who want a pet on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pururun!-shizuku-chan---meiro-no-mori-no-doubutsu-tachi-japan', 'NDS', 'Pururun! Shizuku-chan - Meiro no Mori no Doubutsu-tachi (Japan)', '2007', 'Educational', 'IE Institute', '1', 'Educational Adventure', 'Adventure / Maze.', 'Help Shizuku-chan navigate the animal forest.', 'Maze-based adventure based on the Japanese anime.', 'Pururun! Shizuku-chan features the raindrop sprite in a series of environmental puzzles. Use the stylus to guide characters through tricky mazes and help the forest animals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pururun!-shizuku-chan-aha---ds-drill-kokugo-japan', 'NDS', 'Pururun! Shizuku-chan Aha - DS Drill Kokugo (Japan)', '2008', 'Educational', 'IE Institute', '1', 'Language Training', 'Educational / Language.', 'Master Japanese Kanji and grammar with Shizuku-chan.', 'Fun language drill for Japanese students.', 'DS Drill Kokugo uses the Shizuku-chan characters to teach Japanese literacy. Practice writing and reading through interactive drills designed for primary school children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pururun!-shizuku-chan-aha---ds-drill-sansuu-japan', 'NDS', 'Pururun! Shizuku-chan Aha - DS Drill Sansuu (Japan)', '2008', 'Educational', 'IE Institute', '1', 'Math Training', 'Educational / Math.', 'Improve your math skills with fun raindrop puzzles.', 'Mathematics training based on the Shizuku-chan anime.', 'DS Drill Sansuu makes math entertaining. Solve addition, subtraction, and logic problems with the help of the colorful raindrop cast in this engaging Japanese educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puss-in-boots-europe-enfrdeesitnl', 'NDS', 'Puss in Boots (Europe) (En,Fr,De,Es,It,Nl)', '2011', 'Action Game', 'Locomotive Games', '1', 'Platform Action', 'Action / Platformer.', 'Master the sword and save the village.', 'Movie tie-in adventure starring the famous cat.', 'Puss in Boots (Europe) brings the DreamWorks hero to life. Engage in stylish sword-fighting mini-games and navigate platforming levels using the touch screen in this multi-language hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puss-in-boots-usa-enfres', 'NDS', 'Puss in Boots (USA) (En,Fr,Es)', '2011', 'Action Game', 'Locomotive Games', '1', 'Platform Action', 'Action / Platformer.', 'Master the sword and save the village.', 'North American release of the Puss in Boots game.', 'Play as the swashbuckling feline in Puss in Boots (USA). Featuring the voice of the film and frantic action-platforming, it’s a swashbuckling adventure for fans of the Shrek universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-pop-fever-europe-enja', 'NDS', 'Puyo Pop Fever (Europe) (En,Ja)', '2003', 'Puzzle', 'Sonic Team', '2', 'Falling Block', 'Falling Block Puzzle.', 'Match Puyos to trigger massive chain reactions.', 'The classic SEGA puzzle reboot for Europe.', 'Puyo Pop Fever (Europe) features a quirky story mode and intense multiplayer. Master the "Fever" mechanic to send massive amounts of garbage to your opponent''s screen in this addictive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-pop-fever-usa-enja', 'NDS', 'Puyo Pop Fever (USA) (En,Ja)', '2003', 'Puzzle', 'Sonic Team', '2', 'Falling Block', 'Falling Block Puzzle.', 'Match Puyos to trigger massive chain reactions.', 'North American release of the Puyo Fever reboot.', 'Puyo Pop Fever (USA) includes both English and Japanese voice options. Battle through the magic school and prove your skills in one of the most balanced competitive puzzle games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-7-english', 'NDS', 'Puyo Puyo 7 (English)', '2009', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Use "Great Transformation" to clear the screen.', 'English fan translation of the 7th Puyo entry.', 'Puyo Puyo 7 (English) allows western fans to enjoy the "Great Transformation" mechanic. Play as Ringo and see characters turn into children or adults to trigger massive chains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-7-japan', 'NDS', 'Puyo Puyo 7 (Japan)', '2009', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Use "Great Transformation" to clear the screen.', 'The 7th main entry in the Puyo Puyo series.', 'Puyo Puyo 7 (Japan) introduces a new cast and the Transformation system. It features various modes, including classic rules and new competitive styles for up to 8 players via wireless.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-fever-japan-enja', 'NDS', 'Puyo Puyo Fever (Japan) (En,Ja)', '2003', 'Puzzle', 'Sonic Team', '2', 'Falling Block', 'Falling Block Puzzle.', 'Master the art of Fever to defeat your rivals.', 'Original Japanese release of Puyo Puyo Fever.', 'Experience the game that revitalized the franchise. Puyo Puyo Fever (Japan) features the iconic art style and the addictive gameplay that defined the series for a new generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-fever-two!-japan', 'NDS', 'Puyo Puyo Fever Two! (Japan)', '2004', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Follow Amitie on a new magical adventure.', 'The expanded sequel to Puyo Puyo Fever.', 'Puyo Puyo Fever Two! (Japan) adds more characters, a deeper story mode, and refined mechanics. It’s a must-play for fans of the colorful world of Primp Town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!---puyopuyo-15th-anniversary-english-v12', 'NDS', 'Puyo Puyo! - Puyopuyo 15th Anniversary (English v1.2)', '2007', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Celebrate 15 years of Puyo with 12 different modes.', 'English fan translation of the 15th anniversary hit.', 'Puyo Puyo! 15th Anniversary (English) brings the ultimate compilation to the west. Enjoy 12 unique game modes and a massive roster of 22 characters in full English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!---puyopuyo-15th-anniversary-japan', 'NDS', 'Puyo Puyo! - Puyopuyo 15th Anniversary (Japan)', '2007', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Celebrate 15 years of Puyo with 12 different modes.', 'The massive 15th anniversary compilation.', 'Puyo Puyo! 15th Anniversary (Japan) is a love letter to fans. It includes rules from every previous game, offering the most variety of any entry in the series on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!---puyopuyo-15th-anniversary-japan-rev-1', 'NDS', 'Puyo Puyo! - Puyopuyo 15th Anniversary (Japan) (Rev 1)', '2007', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Celebrate 15 years of Puyo with 12 different modes.', 'Revised Japanese edition (Rev 1).', 'This revision of the 15th Anniversary edition includes minor bug fixes and balancing tweaks, ensuring a stable competitive experience for Japanese puzzle masters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!---puyopuyo-15th-anniversary-japan-rev-3', 'NDS', 'Puyo Puyo! - Puyopuyo 15th Anniversary (Japan) (Rev 3)', '2007', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Celebrate 15 years of Puyo with 12 different modes.', 'Final revised Japanese edition (Rev 3).', 'The most polished version of the 15th Anniversary title. This Rev 3 edition is the standard for collectors looking for the most stable and bug-free version of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!!---puyopuyo-20th-anniversary-japan', 'NDS', 'Puyo Puyo!! - Puyopuyo 20th Anniversary (Japan)', '2011', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Master 20 different sets of rules and 24 characters.', 'The 20th anniversary celebration of Puyo Puyo.', 'Puyo Puyo!! 20th Anniversary (Japan) is a giant celebration. It features the "Pair Puyo" mode and beautiful 2D animations, making it one of the best-looking games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo!!---puyopuyo-20th-anniversary-english-translation', 'NDS', 'Puyo Puyo!! - Puyopuyo 20th Anniversary English Translation', '2011', 'Puzzle', 'Sonic Team', '4', 'Falling Block', 'Falling Block Puzzle.', 'Master 20 different sets of rules and 24 characters.', 'English fan translation of the 20th anniversary hit.', 'Puyo Puyo!! 20th Anniversary (English) allows you to navigate the massive amount of content and 20 different rule sets in English, making this the definitive competitive Puyo experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble-ds-japan', 'NDS', 'Puzzle Bobble DS (Japan)', '2005', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble Shooter.', 'Match colors to pop bubbles and clear the stage.', 'The first DS entry of the classic "Bust-a-Move".', 'Puzzle Bobble DS (Japan) brings the iconic Taito series to the dual screens. Use the stylus or D-pad to aim Bub and Bob''s launcher in hundreds of challenging puzzle levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble-galaxy-europe-enfrdeesit', 'NDS', 'Puzzle Bobble Galaxy (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Taito', '4', 'Arcade Puzzle', 'Bubble Shooter.', 'Save the galaxy one bubble at a time.', 'Space-themed Puzzle Bobble adventure for Europe.', 'Puzzle Bobble Galaxy (Europe) features a full story mode across various planets. Unlock new power-ups and battle massive bosses in this intergalactic version of the classic bubble shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-chronicles-europe-enfrdeesit', 'NDS', 'Puzzle Chronicles (Europe) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Iron Galaxy', '1', 'Puzzle Strategy', 'Puzzle RPG.', 'Match gems to battle enemies and conquer kingdoms.', 'Hybrid of match-3 puzzle and RPG adventure.', 'Puzzle Chronicles (Europe) takes the "Puzzle Quest" formula and adds a side-scrolling twist. Level up your hero and use logical combos to defeat mythical beasts in this deep and engaging RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-chronicles-usa-enfres', 'NDS', 'Puzzle Chronicles (USA) (En,Fr,Es)', '2010', 'Puzzle', 'Iron Galaxy', '1', 'Puzzle Strategy', 'Puzzle RPG.', 'Match gems to battle enemies and conquer kingdoms.', 'North American release of the puzzle-RPG hybrid.', 'Conquer the world through the power of puzzles in Puzzle Chronicles (USA). Featuring a deep loot system and competitive multiplayer, it’s a perfect blend of strategy and addictive logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-city-germany', 'NDS', 'Puzzle City (Germany)', '2006', 'Puzzle', 'Easy Interactive', '1', 'Logic Puzzle', 'Puzzle / Management.', 'Build a thriving city by solving match-3 puzzles.', 'German version of the city-building puzzler.', 'Puzzle City (Germany) challenges you to manage urban growth. Clear tiles to earn building materials and transform your small town into a massive German metropolis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-city-usa', 'NDS', 'Puzzle City (USA)', '2006', 'Puzzle', 'Easy Interactive', '1', 'Logic Puzzle', 'Puzzle / Management.', 'Build a thriving city by solving match-3 puzzles.', 'North American release of Puzzle City.', 'Use your puzzle-solving skills to become a master architect in Puzzle City (USA). Plan your zones carefully and clear rows to unlock new skyscrapers and city landmarks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-de-harvest-moon-usa', 'NDS', 'Puzzle de Harvest Moon (USA)', '2007', 'Puzzle', 'Natsume', '1', 'Tile Puzzle', 'Competitive Puzzle.', 'Match crops and items to outscore your farm rivals.', 'Harvest Moon themed match-3 puzzle for USA.', 'Puzzle de Harvest Moon (USA) features your favorite farm characters in a fast-paced puzzle arena. Match seeds and crops on the touch screen to clear your field and hinder your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-expedition-usa', 'NDS', 'Puzzle Expedition (USA)', '2007', 'Puzzle', 'MumboJumbo', '1', 'Logic Puzzle', 'Logic Puzzle / Platform.', 'Guide characters to the exit by moving blocks.', 'Strategic block-pushing adventure for the USA.', 'Puzzle Expedition (USA) focuses on two explorers navigating 100 levels. Use physics and logic to move blocks, create paths, and avoid traps in this brain-teasing archaeological quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-kingdoms-europe-enfrdeesit', 'NDS', 'Puzzle Kingdoms (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Infinite Interactive', '1', 'Strategy Puzzle', 'Puzzle RPG / Strategy.', 'Conquer kingdoms by winning match-3 battles.', 'Strategic kingdom-conquest puzzle for Europe.', 'Puzzle Kingdoms (Europe) combines troop management with grid-based puzzles. Match symbols to command your army, cast spells, and capture castles in this multi-language strategic epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-kingdoms-usa-enfrdeesit', 'NDS', 'Puzzle Kingdoms (USA) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Infinite Interactive', '1', 'Strategy Puzzle', 'Puzzle RPG / Strategy.', 'Conquer kingdoms by winning match-3 battles.', 'North American release of the fantasy puzzle-sim.', 'Lead your heroes to victory in Puzzle Kingdoms (USA). Level up your commanders and use your tactical wits to solve puzzles that represent intense medieval battles and sieges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-league-ds-europe-enfrdeesit', 'NDS', 'Puzzle League DS (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Nintendo', '2', 'Action Puzzle', 'Competitive Puzzle.', 'Swap blocks to create matches and clear the screen.', 'The definitive European version of Panel de Pon.', 'Puzzle League DS (Europe) is a fast-paced, addictive logic game. Compete against friends locally or via Wi-Fi, featuring touch-screen block swapping and a wide variety of challenge modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-mate-ds---crossword-mate-japan', 'NDS', 'Puzzle Mate DS - Crossword Mate (Japan)', '2008', 'Puzzle', 'SilverStar', '1', 'Crossword Puzzle', 'Logic Puzzle / Words.', 'Solve various crossword grids using the stylus.', 'Portable crossword collection for the Japanese market.', 'Puzzle Mate DS: Crossword Mate features a user-friendly interface for solving traditional word puzzles. Perfect for daily mental exercise and vocabulary building on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-mate-ds---nanpure-mate-japan', 'NDS', 'Puzzle Mate DS - Nanpure Mate (Japan)', '2008', 'Puzzle', 'SilverStar', '1', 'Number Puzzle', 'Logic Puzzle / Sudoku.', 'Fill the 9x9 grid with numbers correctly.', 'Dedicated Sudoku collection for Japan.', 'Puzzle Mate DS: Nanpure Mate offers hundreds of Sudoku puzzles. With multiple difficulty levels and a helpful note-taking system, it''s a solid choice for "Nanpure" enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-mate-ds---oekaki-mate-japan', 'NDS', 'Puzzle Mate DS - Oekaki Mate (Japan)', '2008', 'Puzzle', 'SilverStar', '1', 'Drawing Puzzle', 'Logic Puzzle / Nonogram.', 'Reveal hidden pictures by filling in the grid.', 'Picture-drawing logic puzzles for Japan.', 'Puzzle Mate DS: Oekaki Mate features the classic nonogram gameplay. Use numbers to determine which cells to fill, slowly revealing pixel-art illustrations as you solve each stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest---challenge-of-the-warlords-europe', 'NDS', 'Puzzle Quest - Challenge of the Warlords (Europe)', '2007', 'Puzzle', 'Endless Loop Studios', '1', 'Match-3 RPG', 'Puzzle RPG.', 'Defeat monsters and level up your hero in Etheria.', 'The original award-winning Puzzle-RPG for Europe.', 'Puzzle Quest (Europe) blends deep RPG storytelling with match-3 mechanics. Battle orcs and undead by matching gems, earning gold and XP to learn new spells and craft legendary gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest---challenge-of-the-warlords-europe-enfrdeesit', 'NDS', 'Puzzle Quest - Challenge of the Warlords (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Endless Loop Studios', '1', 'Match-3 RPG', 'Puzzle RPG.', 'Defeat monsters and level up your hero in Etheria.', 'Multi-language European edition of the RPG hit.', 'Experience the quest that started a genre in five languages. This version of Puzzle Quest: Challenge of the Warlords offers a deep, immersive world where every battle is a logic puzzle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest---challenge-of-the-warlords-usa', 'NDS', 'Puzzle Quest - Challenge of the Warlords (USA)', '2007', 'Puzzle', 'Endless Loop Studios', '1', 'Match-3 RPG', 'Puzzle RPG.', 'Defeat monsters and level up your hero in Etheria.', 'North American release of the Puzzle-RPG classic.', 'Puzzle Quest (USA) is a masterpiece of game design. Master the battle board, capture mounts, and build your own citadel in this incredibly addictive hybrid of logic and adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest---galactrix-europe-enfrdeesit', 'NDS', 'Puzzle Quest - Galactrix (Europe) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Infinite Interactive', '1', 'Sci-Fi Match-3', 'Puzzle RPG / Sci-Fi.', 'Pilot your ship through the galaxy in hex-based battles.', 'Sci-fi themed sequel to Puzzle Quest for Europe.', 'Puzzle Quest: Galactrix (Europe) introduces hexagonal tiles and gravity mechanics. Explore a massive universe, trade goods, and battle enemy ships in a deep space-faring RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest---galactrix-usa-enfrdeesit', 'NDS', 'Puzzle Quest - Galactrix (USA) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Infinite Interactive', '1', 'Sci-Fi Match-3', 'Puzzle RPG / Sci-Fi.', 'Pilot your ship through the galaxy in hex-based battles.', 'North American release of the galactic puzzle RPG.', 'Customize your spaceship and conquer the stars in Puzzle Quest: Galactrix (USA). Featuring a new tactical layer and a complex faction system, it''s a stellar evolution of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest-2-europe-enfrdeesit', 'NDS', 'Puzzle Quest 2 (Europe) (En,Fr,De,Es,It)', '2010', 'Puzzle', 'Infinite Interactive', '1', 'Match-3 RPG', 'Puzzle RPG.', 'Venture into dungeons and solve the mystery of Verloren.', 'The highly polished sequel to the original hit.', 'Puzzle Quest 2 (Europe) returns to fantasy roots. Featuring a more detailed map and a refined battle system, you must navigate dangerous ruins and use your puzzle skills to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-quest-2-usa-enfres', 'NDS', 'Puzzle Quest 2 (USA) (En,Fr,Es)', '2010', 'Puzzle', 'Infinite Interactive', '1', 'Match-3 RPG', 'Puzzle RPG.', 'Venture into dungeons and solve the mystery of Verloren.', 'North American release of the acclaimed sequel.', 'Choose your class and dive into the depths of Gordor''s castle in Puzzle Quest 2 (USA). Use the touch screen to cast powerful abilities and solve environmental puzzles in this RPG epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series---jigsaw-puzzle---koinu-mekuri-hen-japan', 'NDS', 'Puzzle Series - Jigsaw Puzzle - Koinu Mekuri Hen (Japan)', '2006', 'Puzzle', 'Success', '1', 'Jigsaw Puzzle', 'Jigsaw Puzzle.', 'Assemble cute photos of puppies.', 'Dog-themed jigsaw collection for Japan.', 'Part of the Puzzle Series, Koinu Mekuri Hen features high-resolution photos of various puppy breeds. Relax and piece together adorable images using the stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series---jigsaw-puzzle---koneko-mekuri-hen-japan', 'NDS', 'Puzzle Series - Jigsaw Puzzle - Koneko Mekuri Hen (Japan)', '2006', 'Puzzle', 'Success', '1', 'Jigsaw Puzzle', 'Jigsaw Puzzle.', 'Assemble cute photos of kittens.', 'Cat-themed jigsaw collection for Japan.', 'This entry in the Puzzle Series focuses on feline friends. Solve dozens of puzzles featuring different kittens in various playful and cozy poses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series---jigsaw-puzzle---oden-kun-japan', 'NDS', 'Puzzle Series - Jigsaw Puzzle - Oden-kun (Japan)', '2007', 'Puzzle', 'Success', '1', 'Jigsaw Puzzle', 'Jigsaw Puzzle.', 'Complete puzzles based on the Oden-kun anime.', 'Anime-themed jigsaw puzzle game for Japan.', 'Puzzle Series: Oden-kun brings the popular character to the DS. Assemble colorful illustrations from the series in this child-friendly and relaxing puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series---jigsaw-puzzle---oden-kun-2-japan', 'NDS', 'Puzzle Series - Jigsaw Puzzle - Oden-kun 2 (Japan)', '2008', 'Puzzle', 'Success', '1', 'Jigsaw Puzzle', 'Jigsaw Puzzle.', 'Complete puzzles based on the Oden-kun anime.', 'Second Oden-kun puzzle collection for Japan.', 'Oden-kun 2 features more complex images and new artwork from the anime. Perfect for fans of the series looking for a portable and charming jigsaw challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-1---jigsaw-puzzle-japan', 'NDS', 'Puzzle Series Vol. 1 - Jigsaw Puzzle (Japan)', '2005', 'Puzzle', 'Success', '1', 'Jigsaw Puzzle', 'Jigsaw Puzzle.', 'Assemble various artistic and scenic puzzles.', 'Hudson Soft''s first puzzle volume for Japan.', 'Puzzle Series Vol. 1: Jigsaw Puzzle offers a wide range of categories, from landscapes to art. Use the DS dual screens to manage your pieces and complete your masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-10---hitori-ni-shitekure-japan', 'NDS', 'Puzzle Series Vol. 10 - Hitori ni Shitekure (Japan)', '2009', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Shade cells so that no two shaded cells touch.', 'The Japanese logic game "Hitori" for DS.', 'Vol. 10: Hitori ni Shitekure brings the classic Nikoli puzzle to the handheld. Use logic and elimination to solve increasingly difficult number-shading challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-11---nurikabe-japan', 'NDS', 'Puzzle Series Vol. 11 - Nurikabe (Japan)', '2009', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Create a continuous wall based on number clues.', 'The Japanese logic game "Nurikabe" for DS.', 'Vol. 11: Nurikabe is a deep logic experience. Connect "islands" and build the "sea" according to the rules in this highly addictive Japanese puzzle volume.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-12---bijutsukan-japan', 'NDS', 'Puzzle Series Vol. 12 - Bijutsukan (Japan)', '2009', 'Puzzle', 'Success', '1', 'Art Puzzle', 'Logic Puzzle.', 'Draw lines to partition the grid based on numbers.', 'The Japanese logic game "Akari / Museum" for DS.', 'Vol. 12: Bijutsukan challenges you to place lightbulbs in a museum to illuminate the entire floor without them shining on each other. A brilliant spatial logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-13---kanji-puzzle-japan', 'NDS', 'Puzzle Series Vol. 13 - Kanji Puzzle (Japan)', '2009', 'Puzzle', 'Success', '1', 'Educational Puzzle', 'Logic Puzzle / Kanji.', 'Solve puzzles based on Japanese characters.', 'Educational Kanji puzzle game for Japan.', 'Vol. 13: Kanji Puzzle tests your knowledge of Japanese writing. Solve crossword-style grids and word games focused on different Kanji characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-2---crossword-japan', 'NDS', 'Puzzle Series Vol. 2 - Crossword (Japan)', '2005', 'Puzzle', 'Success', '1', 'Crossword Puzzle', 'Logic Puzzle / Words.', 'Solve traditional Japanese crosswords.', 'Word-based puzzle collection from Hudson Soft.', 'Vol. 2: Crossword features a variety of grid sizes and difficulty levels. Use the stylus to write in your answers in this classic Japanese linguistic challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-2---crossword-japan-rev-1', 'NDS', 'Puzzle Series Vol. 2 - Crossword (Japan) (Rev 1)', '2005', 'Puzzle', 'Success', '1', 'Crossword Puzzle', 'Logic Puzzle / Words.', 'Solve traditional Japanese crosswords.', 'Revised edition of the Japanese crossword game.', 'This Revision 1 of Crossword (Japan) includes technical improvements and a more refined handwriting recognition system for a better user experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-3---sudoku-japan', 'NDS', 'Puzzle Series Vol. 3 - Sudoku (Japan)', '2005', 'Puzzle', 'Success', '1', 'Number Puzzle', 'Logic Puzzle / Sudoku.', 'Fill the grid with numbers 1 through 9.', 'The quintessential Sudoku game for DS.', 'Vol. 3: Sudoku brought the worldwide craze to the DS with Hudson Soft''s signature polish. Featuring hundreds of hand-crafted puzzles from the masters at Nikoli.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-4---kakuro-japan', 'NDS', 'Puzzle Series Vol. 4 - Kakuro (Japan)', '2006', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Fill the grid with numbers that sum to the clues.', 'The addictive "Cross-Sums" game for Japan.', 'Vol. 4: Kakuro is a perfect blend of Sudoku and crosswords. Use your math skills to find the right combinations of numbers in this challenging logic volume.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-5---slither-link-japan', 'NDS', 'Puzzle Series Vol. 5 - Slither Link (Japan)', '2006', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Connect dots to form a single continuous loop.', 'The classic Japanese loop-making puzzle.', 'Vol. 5: Slither Link is widely considered one of the best logic games on DS. Follow the numerical clues to draw a path that never crosses itself in this pure logic hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-6---illust-logic-japan', 'NDS', 'Puzzle Series Vol. 6 - Illust Logic (Japan)', '2006', 'Puzzle', 'Success', '1', 'Picture Logic', 'Logic Puzzle / Nonogram.', 'Reveal illustrations through numerical clues.', 'Hudson''s take on the Nonogram genre for Japan.', 'Vol. 6: Illust Logic offers dozens of "picture cross" puzzles. Use the stylus to fill the grid and discover the hidden pixel-art images hidden within.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-7---crossword-2-japan', 'NDS', 'Puzzle Series Vol. 7 - Crossword 2 (Japan)', '2007', 'Puzzle', 'Success', '1', 'Crossword Puzzle', 'Logic Puzzle / Words.', 'Solve more complex Japanese crosswords.', 'Second volume of crosswords in the series.', 'Vol. 7: Crossword 2 features an expanded dictionary and larger grids. Challenge your Japanese vocabulary with hundreds of new puzzles and daily training modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-series-vol-8---nankuro-japan', 'NDS', 'Puzzle Series Vol. 8 - Nankuro (Japan)', '2007', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Logic Puzzle / Words.', 'Fill the grid based on character frequency.', 'The Japanese "Nankuro" word puzzle for DS.', 'Vol. 8: Nankuro is a unique type of crossword where no clues are given, only numbers representing different characters. Use pattern recognition to solve the entire grid.');
