INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-time-usa', 'NDS', 'Puzzle Time (USA)', '2006', 'Puzzle', 'Oxygen Interactive', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Solve a variety of quick puzzles to pass the time.', 'Casual puzzle collection for North America.', 'Puzzle Time (USA) offers a mix of classic logic games like Sudoku, Crosswords, and Word Searches. Designed for short play sessions, it’s the perfect companion for commuters looking to keep their minds sharp.');
