INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzler-world-2011-europe', 'NDS', 'Puzzler World 2011 (Europe)', '2011', 'Puzzle', 'Ideas Pad', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Complete over 1,200 new puzzles and mini-games.', '2011 edition of the popular puzzle franchise.', 'Puzzler World 2011 (Europe) expands the formula with more content than ever. Features updated visuals and a refined touch interface for the ultimate portable puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quest-braintainment-netherlands', 'NDS', 'Quest Braintainment (Netherlands)', '2008', 'Educational', 'Davilex', '1', 'Brain Training', 'Educational / Trivia.', 'Answer questions based on the popular "Quest" magazine.', 'Dutch general knowledge and science trivia.', 'Quest Braintainment (Netherlands) tests your knowledge of history, science, and nature. Based on the hit magazine, it offers an engaging way to learn new facts through interactive quizzes.');
