INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('questions-pour-un-champion---le-jeu-officiel---edition-speciale-20-ans-france', 'NDS', 'Questions pour un Champion - Le Jeu Officiel - Edition Speciale 20 Ans (France)', '2009', 'Trivia', 'France Télévisions', '2', 'TV Quiz', 'Game Show / Trivia.', 'Win the 20th Anniversary championship of the show.', 'French trivia game based on the hit TV program.', 'Questions pour un Champion (France) brings the intense TV competition to DS. Experience the "9 Points Gagnants" and "Face à Face" modes in this special 20th-anniversary edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quick-yoga-training---learn-in-minutes-a-day-usa-enfrdeesit', 'NDS', 'Quick Yoga Training - Learn in Minutes a Day (USA) (En,Fr,De,Es,It)', '2010', 'Fitness', 'DTP Entertainment', '1', 'Yoga Training', 'Fitness / Lifestyle.', 'Learn and practice yoga poses with step-by-step guides.', 'Portable yoga instructor for the DS.', 'Quick Yoga Training (USA) features dozens of poses and routines. Use the DS to track your progress and learn proper techniques for relaxation and flexibility in just minutes a day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quickspot-usa', 'NDS', 'QuickSpot (USA)', '2008', 'Puzzle', 'Namco', '1', 'Observation Puzzle', 'Observation / Puzzle.', 'Find the differences between two images quickly.', 'Fast-paced "spot the difference" game by Namco.', 'QuickSpot (USA) challenges your eyes and reflexes. Find the hidden anomalies in a variety of artistic photos and drawings before the time runs out in this addictive brain-trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-&-touch-kensaku---mushi-zukan-ds---mushi-o-sagasou-shirabeyou-japan', 'NDS', 'Quiz & Touch Kensaku - Mushi Zukan DS - Mushi o Sagasou Shirabeyou (Japan)', '2008', 'Educational', 'Namco', '1', 'Quiz Game', 'Educational / Nature.', 'Identify and collect insects in a digital encyclopedia.', 'Bug-themed quiz and reference guide for Japan.', 'Mushi Zukan DS (Japan) allows players to search for and study insects. Solve quizzes to unlock detailed information and photos of hundreds of species in this educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-kirameki-star-road-japan', 'NDS', 'Quiz Kirameki Star Road (Japan)', '2008', 'Trivia', 'Hudson Soft', '1', 'Quiz Game', 'Quiz / Dating Sim.', 'Answer trivia questions to win the heart of a star.', 'Unique hybrid of quiz game and idol simulation.', 'Quiz Kirameki Star Road (Japan) combines general knowledge with character interaction. Your trivia performance determines your relationship with the game''s idols as you aim for stardom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-magic-academy-ds---futatsu-no-jikuuseki-japan', 'NDS', 'Quiz Magic Academy DS - Futatsu no Jikuuseki (Japan)', '2008', 'Trivia', 'Konami', '1', 'Quiz Game', 'Quiz / RPG.', 'Compete in magic academy exams against other players.', 'Online-focused quiz adventure for Japan.', 'Quiz Magic Academy DS: Futatsu no Jikuuseki is a deep quiz-RPG. Customize your student and battle through academic trials using the DS''s wireless features to compete with others.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-magic-academy-ds-japan', 'NDS', 'Quiz Magic Academy DS (Japan)', '2008', 'Trivia', 'Konami', '1', 'Quiz Game', 'Quiz / RPG.', 'Climb the ranks of the Magic Academy.', 'The portable debut of the popular arcade series.', 'Quiz Magic Academy DS (Japan) brings the massive arcade hit home. Answer thousands of questions across different categories to level up your wizard and unlock new items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-magic-academy-ds-japan-rev-1', 'NDS', 'Quiz Magic Academy DS (Japan) (Rev 1)', '2008', 'Trivia', 'Konami', '1', 'Quiz Game', 'Quiz / RPG.', 'Climb the ranks of the Magic Academy.', 'Revised Japanese edition of the quiz hit.', 'This Revision 1 of Quiz Magic Academy DS (Japan) includes technical fixes and balanced question sets, ensuring the best possible competitive experience for puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-no-tabi---tetsudou-ryojou-hen-japan', 'NDS', 'Quiz no Tabi - Tetsudou Ryojou Hen (Japan)', '2009', 'Trivia', 'Jupiter', '1', 'Travel Quiz', 'Quiz / Trivia.', 'Travel across Japan by train by answering quizzes.', 'Train-themed travel trivia game for Japan.', 'Quiz no Tabi: Tetsudou Ryojou Hen focuses on Japanese geography and railway history. Answer correctly to reach your next destination and enjoy the scenic digital journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-taxi-germany', 'NDS', 'Quiz Taxi (Germany)', '2009', 'Trivia', 'Deep Silver', '1', 'Quiz Game', 'Game Show / Trivia.', 'Answer questions inside the famous trivia taxi.', 'German trivia game based on the TV show.', 'Quiz Taxi (Germany) puts you in the passenger seat. Answer increasingly difficult questions as you travel through the city to win the virtual fare in this faithful TV adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz!-hexagon-ii-japan', 'NDS', 'Quiz! Hexagon II (Japan)', '2008', 'Trivia', 'Success', '1', 'Quiz Game', 'Game Show / Trivia.', 'Compete in the popular Japanese variety show.', 'Minigame and quiz collection based on the TV hit.', 'Quiz! Hexagon II (Japan) features the cast of the famous variety program. Participate in quirky quiz formats and fast-paced mini-games that capture the humor of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz!-nihongo-ou-japan', 'NDS', 'Quiz! Nihongo-ou (Japan)', '2009', 'Trivia', 'IE Institute', '1', 'Language Quiz', 'Educational / Trivia.', 'Prove your mastery of the Japanese language.', 'Language-focused quiz game for Japan.', 'Quiz! Nihongo-ou tests your knowledge of Kanji, proverbs, and grammar. It’s a challenging but fun way for native speakers and students alike to perfect their Japanese skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rabbids-go-home---a-comedy-adventure-usa-enfres-ndsi-enhanced', 'NDS', 'Rabbids Go Home - A Comedy Adventure (USA) (En,Fr,Es) (NDSi Enhanced)', '2010', 'Adventure', 'Ubisoft', '4', 'Platform Adventure', 'Action / Comedy.', 'Collect human "stuff" to build a tower to the moon.', 'Zany open-world adventure (NDSi Enhanced).', 'Rabbids Go Home (USA) features the chaotic rabbits in a shopping cart. Use the NDSi camera to "put yourself in the game" and create mayhem across various urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rabbids-go-home-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Rabbids Go Home (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Adventure', 'Ubisoft', '4', 'Platform Adventure', 'Action / Comedy.', 'Collect human "stuff" to build a tower to the moon.', 'European release of the Rabbids'' big quest.', 'Experience the slapstick humor of Rabbids Go Home (Europe). This NDSi Enhanced title features physics-based puzzles and racing as you help the Rabbids return to their lunar home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rabbids-party---tv-party-japan', 'NDS', 'Rabbids Party - TV Party (Japan)', '2010', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game.', 'Participate in a crazy TV-themed variety show.', 'Japanese release of "Rabbids TV Party".', 'Rabbids Party: TV Party (Japan) is a collection of over 50 mini-games. Use the stylus and microphone to compete in bizarre parodies of TV shows, commercials, and movies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('race-driver---create-&-race-europe-enfrdeesit', 'NDS', 'Race Driver - Create & Race (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Codemasters', '4', 'Circuit Racing', 'Racing / Strategy.', 'Build your own tracks and win championships.', 'Innovative track-editing and racing hybrid.', 'Race Driver: Create & Race (Europe) lets you draw tracks with the stylus and then race on them. Features licensed cars and real-world circuits alongside its powerful track creator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('race-driver---create-&-race-usa-enfrdeesit', 'NDS', 'Race Driver - Create & Race (USA) (En,Fr,De,Es,It)', '2007', 'Racing', 'Codemasters', '4', 'Circuit Racing', 'Racing / Strategy.', 'Build your own tracks and win championships.', 'North American release of the creative racer.', 'Unleash your inner designer in Race Driver: Create & Race (USA). Share your custom-made tracks with friends via wireless and test your driving skills in high-stakes professional races.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('race-driver---grid-europe-enfrdeesit', 'NDS', 'Race Driver - Grid (Europe) (En,Fr,De,Es,It)', '2009', 'Racing', 'Codemasters', '4', 'Simulation Racing', 'Racing / Simulation.', 'Compete in the world of high-stakes street and pro racing.', 'The DS version of the acclaimed GRID series.', 'Race Driver: GRID (Europe) brings impressive 3D graphics and realistic handling to the DS. Featuring a deep career mode and a track editor, it’s one of the best racers on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radiant-historia-japan', 'NDS', 'Radiant Historia (Japan)', '2010', 'RPG', 'Atlus', '1', 'Turn-Based RPG', 'JRPG.', 'Travel through time to save the world from destruction.', 'The legendary time-travel RPG from ATLUS.', 'Radiant Historia (Japan) is a masterpiece of storytelling. Use the "White Chronicle" to travel between alternate timelines, making choices that reshape history in this deep, turn-based RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radiant-historia-usa', 'NDS', 'Radiant Historia (USA)', '2011', 'RPG', 'Atlus', '1', 'Turn-Based RPG', 'JRPG.', 'Travel through time to save the world from destruction.', 'Acclaimed North American release of Radiant Historia.', 'Radiant Historia (USA) features a unique grid-based combat system and a hauntingly beautiful soundtrack. It is widely considered one of the finest RPGs of the Nintendo DS era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rafa-nadal-tennis-europe-enfrdeesit', 'NDS', 'Rafa Nadal Tennis (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Virtual Toys', '4', 'Tennis Simulation', 'Tennis / Sports.', 'Master the courts and win the Grand Slam.', 'Tennis simulation featuring the legendary Rafa Nadal.', 'Rafa Nadal Tennis (Europe) uses intuitive touch-screen controls for shots and movement. Train your player, manage your career, and face off against the "King of Clay" himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rafa-nadal-tennis-usa-enfr', 'NDS', 'Rafa Nadal Tennis (USA) (En,Fr)', '2008', 'Sports', 'Virtual Toys', '4', 'Tennis Simulation', 'Tennis / Sports.', 'Master the courts and win the Grand Slam.', 'North American release of the Nadal tennis game.', 'Experience professional tennis in Rafa Nadal Tennis (USA). Featuring realistic physics and a variety of court surfaces, it offers a deep career mode and local wireless multiplayer action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ragnarok-ds-korea', 'NDS', 'Ragnarok DS (Korea)', '2008', 'RPG', 'Gravity', '1', 'Action RPG', 'Action RPG.', 'Journey through the world of Rune Midgard.', 'Korean handheld entry of the famous MMO.', 'Ragnarok DS (Korea) translates the classic PC experience to the handheld. Customize your character, join a guild, and battle familiar monsters in this touch-screen optimized RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ragnarok-ds-usa', 'NDS', 'Ragnarok DS (USA)', '2009', 'RPG', 'Gravity', '1', 'Action RPG', 'Action RPG.', 'Journey through the world of Rune Midgard.', 'North American release of the Ragnarok adventure.', 'Embark on an epic quest in Ragnarok DS (USA). Explore massive dungeons, master the job system, and team up with friends via local wireless for challenging cooperative raids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ragnarok-online-ds-japan', 'NDS', 'Ragnarok Online DS (Japan)', '2008', 'RPG', 'Gravity', '1', 'Action RPG', 'Action RPG.', 'Journey through the world of Rune Midgard.', 'Original Japanese release of the Ragnarok RPG.', 'Ragnarok Online DS (Japan) brings the aesthetic and spirit of the MMO to the DS. With a brand new storyline and touch-based combat, it''s a must-play for fans of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rain-drops-usa', 'NDS', 'Rain Drops (USA)', '2009', 'Puzzle', 'Storm City Games', '1', 'Music Puzzle', 'Puzzle / Arcade.', 'Catch falling raindrops to clear the board.', 'Fast-paced color-matching puzzle for USA.', 'Rain Drops (USA) challenges your reflexes. Use the stylus to catch and match colored droplets before they overflow, featuring various game modes including a relaxing Zen mode and a frantic Challenge mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rainbow-islands-revolution-europe', 'NDS', 'Rainbow Islands Revolution (Europe)', '2005', 'Platforming', 'Taito', '1', 'Arcade Platformer', 'Platform / Arcade.', 'Use rainbows to climb to the top of each island.', 'Modern remake of the Taito classic for Europe.', 'Rainbow Islands Revolution (Europe) reinvents the arcade hit. Use the touch screen to draw rainbows that act as platforms and weapons as you climb through colorful, themed worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rainbow-islands-revolution-usa', 'NDS', 'Rainbow Islands Revolution (USA)', '2005', 'Platforming', 'Taito', '1', 'Arcade Platformer', 'Platform / Arcade.', 'Use rainbows to climb to the top of each island.', 'North American release of the Rainbow Islands remake.', 'Experience a new way to play Bubby and Bobby''s adventure in Rainbow Islands Revolution (USA). Master the touch-screen rainbow drawing to defeat bosses and collect hidden gems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('raku-raku-shindenzu-training-ds-japan-rev-1', 'NDS', 'Raku Raku Shindenzu Training DS (Japan) (Rev 1)', '2008', 'Educational', 'Benesse', '1', 'Brain Training', 'Educational / Medical.', 'Learn to read and interpret ECG patterns.', 'Professional medical training tool for Japan.', 'Raku Raku Shindenzu Training DS (Japan) is a specialized educational title for healthcare students. It features interactive quizzes and lessons on electrocardiogram analysis in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rango-europe-enfrdeesit', 'NDS', 'Rango (Europe) (En,Fr,De,Es,It)', '2011', 'Adventure', 'Behaviour Interactive', '1', 'Action Adventure', 'Action / Adventure.', 'Survive the Wild West as the heroic lizard Rango.', 'Movie-based western adventure for Europe.', 'Rango (Europe) lets you explore the town of Dirt. Engage in platforming, shooting galleries, and mini-games inspired by the film''s unique humor and visual style in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille---food-frenzy-europe-enfrdeesitel', 'NDS', 'Ratatouille - Food Frenzy (Europe) (En,Fr,De,Es,It,El)', '2007', 'Party', 'Helixe', '4', 'Mini-Game Collection', 'Cooking / Mini-games.', 'Help Remy manage a busy kitchen and serve food.', 'Cooking-focused spin-off of the Pixar movie.', 'Ratatouille: Food Frenzy (Europe) features a variety of culinary mini-games. Use the stylus to chop, sauté, and plate gourmet dishes while managing the chaos of a professional kitchen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille---food-frenzy-usa', 'NDS', 'Ratatouille - Food Frenzy (USA)', '2007', 'Party', 'Helixe', '4', 'Mini-Game Collection', 'Cooking / Mini-games.', 'Help Remy manage a busy kitchen and serve food.', 'North American release of Food Frenzy.', 'Join Remy and Emile in Ratatouille: Food Frenzy (USA). Master kitchen skills through touch-screen challenges and unlock recipes in this fun and frantic cooking adventure for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-europe', 'NDS', 'Ratatouille (Europe)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'Main movie tie-in platformer for Europe.', 'Ratatouille (Europe) follows Remy''s journey through the sewers and streets of Paris. Use stealth and agility to navigate levels, collect ingredients, and avoid detection in Gusteau’s kitchen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-europe-ensvnoda', 'NDS', 'Ratatouille (Europe) (En,Sv,No,Da)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'Nordic localized edition of Ratatouille.', 'This European version features full support for Swedish, Norwegian, and Danish players, bringing Remy''s culinary dreams to life with localized text and intuitive platforming gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-europe-espt', 'NDS', 'Ratatouille (Europe) (Es,Pt)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'Spanish and Portuguese localized edition.', 'Ratatouille (Europe) allows players in Spain and Portugal to experience the Pixar magic. Master the touch-screen mini-games and explore detailed 3D environments from the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-europe-frnl', 'NDS', 'Ratatouille (Europe) (Fr,Nl)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'French and Dutch localized edition.', 'Experience Remy''s adventure in French or Dutch. Help the "little chef" navigate dangerous obstacles and fulfill his destiny in this polished multi-language platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-europe-itel', 'NDS', 'Ratatouille (Europe) (It,El)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'Italian and Greek localized edition.', 'A specialized European release for the Italian and Greek markets. Features the full cinematic story and various kitchen-based mini-games that utilize the DS dual screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-germany', 'NDS', 'Ratatouille (Germany)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'German localized release of Ratatouille.', 'Ratatouille (Germany) offers the complete platforming experience in German. Guide Remy through Gusteau''s restaurant using stealth, speed, and culinary wit to save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ratatouille-usa', 'NDS', 'Ratatouille (USA)', '2007', 'Adventure', 'Heavy Iron Studios', '1', 'Platform Adventure', 'Action / Platformer.', 'Navigate Paris and become a master chef.', 'North American release of the Pixar adventure.', 'Ratatouille (USA) brings the sights and sounds of Paris to the DS. Featuring voice acting from the movie and diverse mission types, it’s a high-quality platformer for Disney fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids---tv-party-europe-enfrdeesitnl', 'NDS', 'Rayman - Raving Rabbids - TV Party (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game.', 'Compete in wacky TV-themed challenges.', 'Rabbids-themed mini-game collection for Europe.', 'TV Party (Europe) features over 50 hilarious games. Use the touch screen and microphone to participate in parodies of cinema and television with the chaotic Raving Rabbids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids---tv-party-usa-enfres', 'NDS', 'Rayman - Raving Rabbids - TV Party (USA) (En,Fr,Es)', '2010', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game.', 'Compete in wacky TV-themed challenges.', 'North American release of TV Party.', 'Get crazy with Rayman: Raving Rabbids TV Party (USA). Featuring a huge variety of slapstick mini-games, it’s a perfect title for multiplayer fun and quick gaming sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids-europe-enfrdeesitnl', 'NDS', 'Rayman - Raving Rabbids (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Party', 'Ubisoft', '4', 'Party Game', 'Action / Platformer.', 'Save Rayman''s world from the Rabbid invasion.', 'The first Rabbids game for the Nintendo DS.', 'Rayman: Raving Rabbids (Europe) is a traditional 2D platformer that introduces the Rabbids as villains. Use Rayman''s powers to fight through levels and reclaim the land from the bunnies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids-usa-enfres', 'NDS', 'Rayman - Raving Rabbids (USA) (En,Fr,Es)', '2006', 'Party', 'Ubisoft', '4', 'Party Game', 'Action / Platformer.', 'Save Rayman''s world from the Rabbid invasion.', 'North American release of Rayman''s bunny battle.', 'Fight the Rabbids in Rayman: Raving Rabbids (USA). This version focuses on classic Rayman action with touch-screen mini-games interspersed throughout the adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids-2-europe-enfrdeesitnl', 'NDS', 'Rayman - Raving Rabbids 2 (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game / Action.', 'Travel the world and defeat the Rabbids'' plans.', 'Sequel to the Rabbids'' first outing.', 'Raving Rabbids 2 (Europe) moves toward a more mini-game-centric format. Travel to different continents and engage in bizarre challenges that test your speed and stylus accuracy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids-2-usa-enfres', 'NDS', 'Rayman - Raving Rabbids 2 (USA) (En,Fr,Es)', '2007', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game / Action.', 'Travel the world and defeat the Rabbids'' plans.', 'North American release of the Rabbids sequel.', 'Join the global invasion in Rayman: Raving Rabbids 2 (USA). With improved graphics and even weirder mini-games, it’s a chaotic journey that highlights the Rabbids'' unique brand of humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---yeopgitokki---tv-party-korea', 'NDS', 'Rayman - Yeopgitokki - TV Party (Korea)', '2010', 'Party', 'Ubisoft', '4', 'Party Game', 'Party Game.', 'Compete in wacky TV-themed challenges.', 'Korean localized version of TV Party.', 'Rayman: Yeopgitokki - TV Party brings the Rabbids'' madness to Korea. Experience all the TV-themed mini-games with fully localized text for the Korean market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-ds-europe-enfrdeesit', 'NDS', 'Rayman DS (Europe) (En,Fr,De,Es,It)', '1999', 'Platforming', 'Ubisoft', '1', '3D Platformer', 'Action / Platformer.', 'Explore the world of Rayman 2 in 3D.', 'Portable port of the classic Rayman 2.', 'Rayman DS (Europe) is a faithful port of the legendary 3D platformer. Explore the Glade of Dreams, collect Lums, and defeat Admiral Razorbeard in this landmark handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-ds-usa-enfres', 'NDS', 'Rayman DS (USA) (En,Fr,Es)', '1999', 'Platforming', 'Ubisoft', '1', '3D Platformer', 'Action / Platformer.', 'Explore the world of Rayman 2 in 3D.', 'North American release of the 3D classic.', 'Experience one of the greatest platformers of all time on the go. Rayman DS (USA) features expansive 3D levels and refined controls for the DS hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-over-luigi', 'NDS', 'Rayman over Luigi', '2010', 'Platforming', 'Homebrew', '1', 'Fan Game', 'Action / Adventure.', 'Explore a Rayman world with Luigi elements.', 'Fan-made ROM hack/crossover.', 'Rayman over Luigi is a creative modification that swaps characters or mechanics, offering a unique "what if" scenario for fans of both legendary platforming franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('reader-rabbit---kindergarten-usa', 'NDS', 'Reader Rabbit - Kindergarten (USA)', '2009', 'Educational', 'The Learning Company', '1', 'Educational Adventure', 'Educational / Mini-games.', 'Learn essential skills through fun activities.', 'Educational adventure for young children.', 'Reader Rabbit: Kindergarten (USA) focuses on early literacy and math. Join Reader Rabbit and friends in a series of interactive games designed to build confidence in young learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ready-steady-cook---the-game-europe', 'NDS', 'Ready Steady Cook - The Game (Europe)', '2007', 'Cooking', 'Zushi Games', '4', 'TV Show Game', 'Cooking / Simulation.', 'Compete in the kitchen against the clock.', 'Cooking game based on the BBC TV show.', 'Ready Steady Cook (Europe) features the "Green Bean" vs. "Red Tomato" challenge. Use the stylus to prepare ingredients and cook recipes under pressure to win the vote.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-adventures---pet-vet-europe-deesit', 'NDS', 'Real Adventures - Pet Vet (Europe) (De,Es,It)', '2008', 'Simulation', 'Kritzelkratz 3000', '1', 'Veterinary Simulation', 'Vet Simulation.', 'Treat and care for a variety of domestic animals.', 'Animal hospital simulator for Southern Europe.', 'Pet Vet (Europe) tasks you with diagnosing and curing sick pets. Manage your clinic, perform examinations with the stylus, and ensure the happiness of your furry patients.');
