INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-adventures---pet-vet-europe-ennlsvnoda', 'NDS', 'Real Adventures - Pet Vet (Europe) (En,Nl,Sv,No,Da)', '2008', 'Simulation', 'Kritzelkratz 3000', '1', 'Veterinary Simulation', 'Vet Simulation.', 'Treat and care for a variety of domestic animals.', 'Northern European version of the vet sim.', 'This version of Real Adventures: Pet Vet provides localized support for Dutch and Scandinavian languages, making the educational animal care experience accessible to more young fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-adventures---wild-horses---the-quest-for-the-golden-horse-europe-enfrdeesit', 'NDS', 'Real Adventures - Wild Horses - The Quest for the Golden Horse (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Kritzelkratz 3000', '1', 'Horse Adventure', 'Horse Simulation.', 'Rescue wild horses and find the Golden Horse.', 'Equestrian adventure and care game for Europe.', 'Wild Horses (Europe) combines horse grooming with an epic quest. Explore vast landscapes, bond with your stallion, and solve mysteries to protect the herd in five languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-adventures---wild-horses---the-quest-for-the-golden-horse-europe-ennlsvnoda', 'NDS', 'Real Adventures - Wild Horses - The Quest for the Golden Horse (Europe) (En,Nl,Sv,No,Da)', '2009', 'Adventure', 'Kritzelkratz 3000', '1', 'Horse Adventure', 'Horse Simulation.', 'Rescue wild horses and find the Golden Horse.', 'Nordic localized version of the horse adventure.', 'Join the quest for the Golden Horse in this specialized Northern European edition. Features detailed horse care mechanics and an engaging story for horse lovers of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-crimes---jack-the-ripper-europe-enfrdees', 'NDS', 'Real Crimes - Jack the Ripper (Europe) (En,Fr,De,Es)', '2009', 'Adventure', 'Bluewater Games', '1', 'Hidden Object', 'Hidden Object / Mystery.', 'Solve the mystery of London''s most famous serial killer.', 'Crime investigation and hidden object game.', 'Real Crimes: Jack the Ripper (Europe) takes you back to 1888. Search for clues across detailed Victorian environments and solve puzzles to unmask the Ripper in this multi-language mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-football-2008-europe-enfrdeesitnl', 'NDS', 'Real Football 2008 (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Sports', 'Gameloft', '4', 'Soccer Simulation', 'Soccer / Sports.', 'Lead your team to international glory on the pitch.', 'European release of Gameloft''s soccer series.', 'Real Football 2008 (Europe) features intuitive touch-screen controls and a deep management mode. Take control of licensed players and master the art of the goal in this multilingual sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-football-2009-europe-enfrdeesitnl', 'NDS', 'Real Football 2009 (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Sports', 'Gameloft', '4', 'Soccer Simulation', 'Soccer / Sports.', 'Win the championship and manage your squad.', 'Advanced soccer simulation for the European market.', 'Real Football 2009 (Europe) improves the graphics and AI of its predecessor. With more teams and refined tactical options, it offers a premier portable soccer experience on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-soccer-2008-usa-enfres', 'NDS', 'Real Soccer 2008 (USA) (En,Fr,Es)', '2007', 'Sports', 'Gameloft', '4', 'Soccer Simulation', 'Soccer / Sports.', 'Conquer the league and score the winning goal.', 'North American release of Real Football 2008.', 'Real Soccer 2008 (USA) brings professional football to your fingertips. Master free kicks and penalties using the stylus and climb the world rankings in this fast-paced sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-soccer-2009-usa-enfres', 'NDS', 'Real Soccer 2009 (USA) (En,Fr,Es)', '2008', 'Sports', 'Gameloft', '4', 'Soccer Simulation', 'Soccer / Sports.', 'Build a dream team and win the cup.', 'North American release of Real Football 2009.', 'Real Soccer 2009 (USA) features enhanced animations and 3D stadiums. Utilize the touch screen to execute precise passes and lead your favorite national team to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---amoureux-pour-la-vie-france', 'NDS', 'Real Stories - Amoureux pour la Vie (France)', '2008', 'Simulation', 'Ubisoft', '1', 'Life Simulation', 'Life simulation.', 'Navigate the world of dating and find true love.', 'Romantic life simulation for the French market.', 'Real Stories: Amoureux pour la Vie (France) focuses on relationships. Manage your character''s social life, choose your outfits, and navigate the ups and downs of high school romance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---babies-france', 'NDS', 'Real Stories - Babies (France)', '2008', 'Simulation', 'Ubisoft', '1', 'Life Simulation', 'Life simulation.', 'Take care of virtual babies and keep them happy.', 'Childcare and nursery simulation for France.', 'Real Stories: Babies (France) puts you in charge of a day care center. Use the stylus to feed, bathe, and play with babies, ensuring their needs are met to become a top nanny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---best-friends---mon-poulain-mon-cheval-europe-enfrdeitsvnoda', 'NDS', 'Real Stories - Best Friends - Mon Poulain, Mon Cheval (Europe) (En,Fr,De,It,Sv,No,Da)', '2009', 'Simulation', 'Ubisoft', '1', 'Horse Care Simulation', 'Horse simulation.', 'Care for your horse and train it for competitions.', 'Equestrian care and riding sim for Europe.', 'Best Friends: Mon Poulain, Mon Cheval focuses on the bond between rider and horse. Manage your stable and compete in show jumping across several European languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---cheval-academy-france', 'NDS', 'Real Stories - Cheval Academy (France)', '2008', 'Simulation', 'Ubisoft', '1', 'Horse Academy Simulation', 'Horse simulation.', 'Train at the academy and become a pro rider.', 'Academic horse riding simulation for France.', 'Real Stories: Cheval Academy (France) features a structured story where you learn different riding disciplines. Balance your studies with horse grooming to win the year-end tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---fashion-shop-europe-enfr', 'NDS', 'Real Stories - Fashion Shop (Europe) (En,Fr)', '2008', 'Simulation', 'Ubisoft', '1', 'Fashion Simulation', 'Shop management.', 'Manage a clothing store and set fashion trends.', 'Fashion business and boutique simulator.', 'Real Stories: Fashion Shop (Europe) lets you design clothes and manage your stock. Attract customers with your window displays and build a fashion empire in this English-French release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---mijn-babycreche-europe-ennlsvnoda', 'NDS', 'Real Stories - Mijn Babycreche (Europe) (En,Nl,Sv,No,Da)', '2009', 'Simulation', 'Ubisoft', '1', 'Baby Care Simulation', 'Life simulation.', 'Manage a busy day care center for toddlers.', 'Childcare simulation for Northern Europe.', 'Mijn Babycreche (Netherlands) focuses on the daily operations of a nursery. Keep the children entertained and healthy in this localized edition for Dutch and Scandinavian players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---mission-equitation-france', 'NDS', 'Real Stories - Mission Equitation (France)', '2008', 'Simulation', 'Ubisoft', '1', 'Equestrian Simulation', 'Horse simulation.', 'Complete secret missions on horseback.', 'Adventure-themed horse riding game for France.', 'Real Stories: Mission Equitation (France) blends horse riding with exploration. Complete various quests and puzzles across beautiful landscapes to protect your stable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---mon-hotel-de-reve-france', 'NDS', 'Real Stories - Mon Hotel de Reve (France)', '2008', 'Simulation', 'Ubisoft', '1', 'Hotel Management', 'Hotel management.', 'Build and run the hotel of your dreams.', 'Business and hospitality simulation for France.', 'Real Stories: Mon Hotel de Reve (France) challenges you to manage finances and guest satisfaction. Expand your facilities and decorate rooms to earn a five-star rating.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---passion-4-fashion-europe-ennlsvnoda', 'NDS', 'Real Stories - Passion 4 Fashion (Europe) (En,Nl,Sv,No,Da)', '2009', 'Simulation', 'Ubisoft', '1', 'Fashion Simulation', 'Fashion simulation.', 'Rise to the top of the fashion industry.', 'Fashion design and career sim for Northern Europe.', 'Passion 4 Fashion (Europe) focuses on creating unique collections. Compete in catwalk shows and manage your reputation as a designer in this multi-language Northern edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-stories---veterinaire---mission-australie-france', 'NDS', 'Real Stories - Veterinaire - Mission Australie (France)', '2009', 'Simulation', 'Ubisoft', '1', 'Veterinary Simulation', 'Vet simulation.', 'Save wild animals in the Australian outback.', 'Wildlife veterinary simulation set in Australia.', 'Veterinaire: Mission Australie (France) tasks you with curing exotic animals. Use the stylus to perform surgery and care for kangaroos and koalas in the rugged outback.');
