INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-time-conflict---shogun-empires-usa', 'NDS', 'Real Time Conflict - Shogun Empires (USA)', '2008', 'Strategy', 'Chillingo', '1', 'Real-Time Strategy', 'RTS / Strategy.', 'Lead armies to unite Japan during the Sengoku period.', 'Grand strategy and tactical combat for USA.', 'Real Time Conflict: Shogun Empires (USA) features massive real-time battles. Manage your resources and command your troops on the touch screen to conquer rival clans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('really-really!---rearea-ds-japan', 'NDS', 'Really Really! - ReaRea DS (Japan)', '2007', 'Party', 'MediaKite', '4', 'Mini-Game Collection', 'Visual Novel.', 'Navigate a romantic story with branching paths.', 'Anime-style visual novel and mini-game collection.', 'Really Really! (Japan) is a spin-off of the "Shuffle!" series. Use your memory to reconstruct the protagonist''s lost memories through dialogue and interactive puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('recettes-de-cuisine-avec-cyril-lignac-france', 'NDS', 'Recettes de Cuisine avec Cyril Lignac (France)', '2009', 'Educational', 'Mindscape', '1', 'Cooking Education', 'Cooking / Simulation.', 'Learn to cook with celebrity chef Cyril Lignac.', 'Interactive cookbook and cooking sim for France.', 'Recettes de Cuisine avec Cyril Lignac (France) features over 100 recipes. Follow the chef''s instructions through videos and mini-games to master French cuisine on your DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('red-bull-bc-one-europe-enfrdeesit', 'NDS', 'Red Bull BC One (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', '10TACLE Studios', '2', 'Breakdance Competition', 'Rhythm / Action.', 'Battle other breakdancers in the BC One tournament.', 'Breakdancing and rhythm game for Europe.', 'Red Bull BC One (Europe) uses the stylus to perform complex power moves and freezes. Hit the beat perfectly to out-dance your rivals in the ultimate B-Boy competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('red-bull-bc-one-usa-enfrdeesit', 'NDS', 'Red Bull BC One (USA) (En,Fr,De,Es,It)', '2008', 'Sports', '10TACLE Studios', '2', 'Breakdance Competition', 'Rhythm / Action.', 'Battle other breakdancers in the BC One tournament.', 'North American release of the breakdance sim.', 'Become the BC One champion in Red Bull BC One (USA). Featuring licensed music and motion-captured moves, it’s a high-energy rhythm game that captures the spirit of breakdancing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('refined-gold-overhaul', 'NDS', 'Refined Gold Overhaul', '2010', 'Adventure', 'Homebrew', '1', 'Fan Overhaul', 'RPG / Overhaul.', 'Experience a deeper and more balanced Johto.', 'Enhanced ROM hack of Pokémon HeartGold.', 'Refined Gold Overhaul improves the classic Pokémon experience by adding modern features, balancing move-pools, and allowing all 493 Pokémon to be caught in a single game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-adventure---quiz-sangokushi-tsuu-ds-japan', 'NDS', 'Rekishi Adventure - Quiz Sangokushi Tsuu DS (Japan)', '2007', 'Educational', 'Namco', '1', 'History Quiz', 'Quiz / History.', 'Test your knowledge of the Three Kingdoms era.', 'Advanced history trivia game for Japan.', 'Quiz Sangokushi Tsuu DS focuses on the lore of ancient China. Answer hundreds of questions about legendary generals and battles to prove your historical expertise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-gunzou-presents---monoshiri-bakumatsu-ou-japan', 'NDS', 'Rekishi Gunzou Presents - Monoshiri Bakumatsu Ou (Japan)', '2006', 'Educational', 'Namco', '1', 'History Education', 'Educational / History.', 'Learn about the Bakumatsu period of Japan.', 'Historical reference and quiz game for Japan.', 'Monoshiri Bakumatsu Ou provides a detailed look at the end of the Tokugawa shogunate. Features quizzes and encyclopedic entries on the era''s key figures and events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-gunzou-presents---monoshiri-sangokushi-japan', 'NDS', 'Rekishi Gunzou Presents - Monoshiri Sangokushi (Japan)', '2006', 'Educational', 'Namco', '1', 'History Education', 'Educational / History.', 'Master the history of the Three Kingdoms.', 'Historical encyclopedia and trivia for Japan.', 'Monoshiri Sangokushi offers a wealth of information about the Romance of the Three Kingdoms. Test your knowledge and learn new facts about Liu Bei, Cao Cao, and Sun Quan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-gunzou-presents---monoshiri-sengoku-ou-japan', 'NDS', 'Rekishi Gunzou Presents - Monoshiri Sengoku Ou (Japan)', '2006', 'Educational', 'Namco', '1', 'History Education', 'Educational / History.', 'Learn about the Sengoku (Warring States) period.', 'Historical reference and quiz game for Japan.', 'Monoshiri Sengoku Ou focuses on the unification of Japan. Explore the lives of Oda Nobunaga and Toyotomi Hideyoshi through challenging quizzes and historical records.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-nouryoku-kentei-kyoukai-kounin---yamakawa-shuppansha-kanshuu---rekiken-ds---nihonshi-sekaishi-japan', 'NDS', 'Rekishi Nouryoku Kentei Kyoukai Kounin - Yamakawa Shuppansha Kanshuu - Rekiken DS - Nihonshi, Sekaishi (Japan)', '2007', 'Educational', 'Namco', '1', 'History Certification', 'Educational / History.', 'Prepare for the official Japanese history exam.', 'Certified historical study guide and quiz for Japan.', 'Rekiken DS features content approved by the History Proficiency Test Association. It covers both Japanese and World history through structured lessons and practice tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-simulation-game---sangokushi-ds-japan', 'NDS', 'Rekishi Simulation Game - Sangokushi DS (Japan)', '2006', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Strategy / Simulation.', 'Command armies to unite China in this classic sim.', 'Handheld port of the legendary Sangokushi (Romance of the Three Kingdoms).', 'Sangokushi DS (Japan) brings Koei''s deep strategy to the dual screens. Use the touch screen to manage your cities, recruit officers, and engage in tactical turn-based warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-simulation-game---sangokushi-ds-japan-rev-2', 'NDS', 'Rekishi Simulation Game - Sangokushi DS (Japan) (Rev 2)', '2006', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Strategy / Simulation.', 'Command armies to unite China in this classic sim.', 'Revised edition (Rev 2) of the first Sangokushi DS.', 'This Revision 2 of Sangokushi DS includes technical optimizations and AI improvements, providing a more stable and challenging experience for strategy enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-simulation-game---sangokushi-ds-2-japan', 'NDS', 'Rekishi Simulation Game - Sangokushi DS 2 (Japan)', '2008', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Strategy / Simulation.', 'Experience a massive upgrade to the strategy formula.', 'Second entry of the Sangokushi series on DS.', 'Sangokushi DS 2 (Japan) features improved graphics and an expanded roster of officers. It introduces new tactical maneuvers and a more intuitive interface for managing your empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-simulation-game---sangokushi-ds-3-japan', 'NDS', 'Rekishi Simulation Game - Sangokushi DS 3 (Japan)', '2010', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Strategy / Simulation.', 'Master the ultimate Three Kingdoms strategy game.', 'Third and final main entry of Sangokushi on DS.', 'Sangokushi DS 3 (Japan) is the most feature-rich version. It includes various scenarios, refined diplomat mechanics, and deep tactical depth that defines the Koei strategy brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rekishi-taisen---gettenka---tenkaichi-battle-royale-japan', 'NDS', 'Rekishi Taisen - Gettenka - Tenkaichi Battle Royale (Japan)', '2008', 'Action', 'Marvelous', '4', 'Battle Royale', 'Card Battle / History.', 'Battle with historical figures in a card-based duel.', 'Arcade-style card battle game based on history.', 'Gettenka: Tenkaichi Battle Royale (Japan) features stylish versions of famous generals. Collect cards and use the touch screen to battle rivals in this fast-paced historical mash-up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('relaxation-puzzle-game---nemurenai-yoru-to-puzzle-no-hi-ni-wa-japan', 'NDS', 'Relaxation Puzzle Game - Nemurenai Yoru to Puzzle no Hi ni wa.... (Japan)', '2009', 'Puzzle', 'Success', '1', 'Relaxation Puzzle', 'Puzzle / Relaxation.', 'Solve puzzles to help you fall asleep.', 'Meditative and calming puzzle game for Japan.', 'Relaxation Puzzle Game is designed to be played before bed. It features soothing music and low-stress logic puzzles intended to help the player relax and unwind.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('remindelight-japan', 'NDS', 'Remindelight (Japan)', '2008', 'Puzzle', 'Success', '1', 'Light-Based Puzzle', 'Action RPG.', 'Solve puzzles and battle monsters in a fantasy world.', 'Stylus-based Japanese action adventure.', 'Remindelight (Japan) uses the touch screen for its unique combat system. Draw symbols to cast magic and swing your weapon while exploring vibrant 3D dungeons in this hidden gem.');
