INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('restaurant-tycoon-europe-enfrdeesitnl', 'NDS', 'Restaurant Tycoon (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Majesco', '1', 'Restaurant Management', 'Business Simulation.', 'Build and manage a successful restaurant empire.', 'Culinary business management simulator.', 'Restaurant Tycoon (Europe) puts you in charge of everything from interior design to menu pricing. Satisfy customers and manage your staff to turn a small cafe into a luxury eatery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('retro-arcade-toppers-europe', 'NDS', 'Retro Arcade Toppers (Europe)', '2010', 'Compilation', 'Namco', '4', 'Retro Arcade Compilation', 'Arcade / Retro.', 'Master classic-style arcade challenges.', 'Collection of retro-inspired arcade games.', 'Retro Arcade Toppers (Europe) features a variety of simple but addictive titles that mimic the golden age of gaming, perfect for quick high-score chasing sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('retro-atari-classics-usa-europe', 'NDS', 'Retro Atari Classics (USA, Europe)', '2005', 'Compilation', 'Atari', '4', 'Classic Games Compilation', 'Arcade / Retro.', 'Play classic Atari hits with updated visuals.', 'Compilation of legendary Atari arcade games.', 'Retro Atari Classics (USA, Europe) features Asteroids, Centipede, and Missile Command. Includes both original versions and "Remix" versions with modern graffiti-style art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('retro-game-challenge-usa', 'NDS', 'Retro Game Challenge (USA)', '2009', 'Simulation', 'Xseed Games', '1', 'Game Development Simulation', 'Retro / Mini-games.', 'Complete challenges in fictional 8-bit games.', 'A love letter to NES-era Japanese gaming.', 'Retro Game Challenge (USA) is based on the "Game Center CX" show. Clear specific goals in variety of fictional retro games to progress through a nostalgic 1980s storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('reversal-challenge-usa', 'NDS', 'Reversal Challenge (USA)', '2009', 'Puzzle', 'D3 Publisher', '1', 'Reflex Puzzle', 'Board Game / Othello.', 'Outmaneuver your opponent in the game of Reversi.', 'Classic Reversi (Othello) simulation.', 'Reversal Challenge (USA) features various difficulty levels and board themes. Master the strategy of flipping your opponent''s pieces to dominate the board in this clean digital version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revo-kart-ds-demo-21', 'NDS', 'Revo Kart DS Demo 2.1', '2009', 'Racing', 'Homebrew', '4', 'Kart Racing Demo', 'Racing / Tech Demo.', 'Test the limits of kart racing on the DS.', 'Advanced homebrew/fan-made karting demo.', 'Revo Kart DS Demo 2.1 showcases impressive 3D environments and kart physics, serving as a technical showcase for what independent developers could achieve on the hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rhapsody---a-musical-adventure-europe-enfr', 'NDS', 'Rhapsody - A Musical Adventure (Europe) (En,Fr)', '2009', 'RPG', 'NIS America', '1', 'Tactical JRPG', 'Strategy RPG.', 'Sing and battle to rescue a kidnapped prince.', 'Musical JRPG with a lighthearted story.', 'Rhapsody: A Musical Adventure (Europe) is a charming RPG featuring puppet-based combat and musical numbers. Use the DS touch screen to navigate menus and command your party.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rhapsody---a-musical-adventure-usa', 'NDS', 'Rhapsody - A Musical Adventure (USA)', '2009', 'RPG', 'NIS America', '1', 'Tactical JRPG', 'Strategy RPG.', 'Sing and battle to rescue a kidnapped prince.', 'North American release of the musical cult classic.', 'Follow Cornet and her puppet Kururu in Rhapsody (USA). This DS version features a revamped turn-based combat system and colorful 2D sprites that look great on the handheld screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rhythm-n-notes---improve-your-music-skills-usa', 'NDS', 'Rhythm ''n Notes - Improve Your Music Skills (USA)', '2010', 'Educational', 'Seven45 Studios', '1', 'Music Education', 'Educational / Music.', 'Improve your ability to read and play music.', 'Interactive music theory and ear trainer.', 'Rhythm ''n Notes (USA) uses the touch screen to teach piano and drums. Practice rhythm, pitch recognition, and basic music notation through fun, repetitive exercises.');
