INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rhythm-heaven-usa', 'NDS', 'Rhythm Heaven (USA)', '2009', 'Rhythm', 'Nintendo', '1', 'Rhythm Action', 'Rhythm / Music.', 'Master bizarre and addictive rhythm mini-games.', 'The legendary rhythm series from the WarioWare team.', 'Rhythm Heaven (USA) features dozens of quirky scenarios, from choir practice to monkey dancing. Hold the DS vertically (Book Style) and flick the stylus to the beat.');
