INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockin-pretty-usa', 'NDS', 'Rockin'' Pretty (USA)', '2009', 'Simulation', 'City Interactive', '1', 'Fashion Simulation', 'Rhythm / Fashion.', 'Perform as a pop idol and customize your look.', 'Idol simulation and rhythm game for the USA.', 'Rockin'' Pretty (USA) combines rhythm-action with fashion. Win musical contests to unlock new outfits and accessories, aiming to become the ultimate stage sensation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe---operate-shooting-star-english', 'NDS', 'Rockman EXE - Operate Shooting Star (English)', '2005', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Battle viruses and navigate the cyber world.', 'English fan translation of the DS remake.', 'Rockman EXE: Operate Shooting Star (English) is a crossover between the Battle Network and Star Force series. Play the original GBA classic with refined DS features and new story content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe---operate-shooting-star-japan', 'NDS', 'Rockman EXE - Operate Shooting Star (Japan)', '2005', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Battle viruses and navigate the cyber world.', 'Remake of the first Battle Network for Japan.', 'Operate Shooting Star (Japan) updates the classic Rockman EXE gameplay with a new Star Force scenario, touch-screen maps, and localized improvements for the DS hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-5-ds---twin-leaders-japan', 'NDS', 'Rockman EXE 5 DS - Twin Leaders (Japan)', '2005', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Lead a team of Navis to save the internet.', 'Dual-version Rockman EXE 5 for the DS.', 'Rockman EXE 5 DS: Twin Leaders (Japan) combines both "Team ProtoMan" and "Team Colonel" on one cartridge. It features dual-slot functionality and NDSi-enhanced play modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-collection-japan', 'NDS', 'Rockman Zero Collection (Japan)', '2010', 'Action', 'Capcom', '1', 'Action Compilation', 'Action / Platformer.', 'Face the ultimate challenge as the legendary Zero.', 'Compilation of all four Rockman Zero titles.', 'Rockman Zero Collection (Japan) brings the difficult GBA classics to the DS. It includes an "Easy Scenario" mode for newcomers and a gallery of unlockable concept art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zx---advent-japan', 'NDS', 'Rockman ZX - Advent (Japan)', '2009', 'Action', 'Capcom', '1', 'Action Platformer', 'Action / Platformer.', 'Explore the world as a Mega Man Model wearer.', 'High-speed action sequel for Japan.', 'Rockman ZX: Advent (Japan) features two protagonists and the ability to "Megamerge" into bosses. It offers a sprawling map and intense boss battles in the classic ZX style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zx-japan', 'NDS', 'Rockman ZX (Japan)', '2006', 'Action', 'Capcom', '1', 'Action Platformer', 'Action / Platformer.', 'Navigate a semi-open world with biometal powers.', 'The first entry in the Rockman ZX series.', 'Rockman ZX (Japan) blends traditional Mega Man action with Metroidvania exploration. Switch between different Biometals to solve puzzles and defeat the Mavericks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rollercoaster-park-europe-enfrnl', 'NDS', 'Rollercoaster Park (Europe) (En,Fr,Nl)', '2008', 'Simulation', 'DSi Games', '1', 'Theme Park Management', 'Strategy / Management.', 'Build and manage your own theme park.', 'Park simulation and management for Europe.', 'Rollercoaster Park (Europe) lets you design death-defying coasters and manage park finances. Ensure your guests are happy and profitable in this deep business simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rollin-rascals-usa', 'NDS', 'Rollin'' Rascals (USA)', '2009', 'Action', 'Zoo Games', '1', 'Action Platformer', 'Puzzle / Arcade.', 'Roll cute characters through obstacle-filled levels.', 'Physics-based puzzle adventure for the USA.', 'Rollin'' Rascals (USA) uses the stylus to tilt and guide your rascals. Navigate dangerous traps and collect items in a variety of colorful and challenging worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rondo-of-swords-usa', 'NDS', 'Rondo of Swords (USA)', '2008', 'RPG', 'Atlus', '1', 'Tactical RPG', 'Strategy RPG.', 'Lead a band of mercenaries using the "Errand" system.', 'High-difficulty tactical RPG for the USA.', 'Rondo of Swords (USA) features a unique movement system where you attack enemies by passing through them. Manage a complex story and deep character progression in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roogoo-attack!-usa-enfrdeesit', 'NDS', 'Roogoo Attack! (USA) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Paramount Digital', '1', 'Physics Puzzle', 'Logic Puzzle.', 'Drop shapes through moving holes to save the planet.', 'Fast-paced spatial reasoning puzzle for the USA.', 'Roogoo Attack! (USA) requires quick reflexes. Align rotating platforms to allow falling shapes to pass through, featuring diverse worlds and competitive multiplayer modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rooms---fushigi-na-ugoku-heya-japan', 'NDS', 'Rooms - Fushigi na Ugoku Heya (Japan)', '2008', 'Puzzle', 'HandyGames', '1', 'Sliding Puzzle', 'Logic Puzzle.', 'Slide rooms to find an exit in a mysterious mansion.', 'Surreal and clever room-sliding puzzle game.', 'Rooms: Fushigi na Ugoku Heya (Japan) is a unique logic game. Move entire sections of a house to navigate your character to the door in this atmospheric and brain-teasing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rooms---the-main-building-europe-enfrdeesit', 'NDS', 'Rooms - The Main Building (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'HandyGames', '1', 'Sliding Puzzle', 'Logic Puzzle.', 'Slide rooms to find an exit in a mysterious mansion.', 'European release of the room-sliding puzzler.', 'Rooms: The Main Building (Europe) features over 100 levels. Use logic and environmental objects like teleporters and ladders to solve the mystery of the shifting mansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rooms---the-main-building-usa-enfres', 'NDS', 'Rooms - The Main Building (USA) (En,Fr,Es)', '2008', 'Puzzle', 'HandyGames', '1', 'Sliding Puzzle', 'Logic Puzzle.', 'Slide rooms to find an exit in a mysterious mansion.', 'North American release of the Rooms puzzle.', 'Master the art of the sliding puzzle in Rooms: The Main Building (USA). With its distinct Victorian aesthetic and challenging gameplay, it’s a standout title for logic fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rosalina-and-luma', 'NDS', 'Rosalina and Luma', '2011', 'Adventure', 'Homebrew', '1', 'Fan Adventure', 'Action / Crossover.', 'Use Rosalina''s cosmic powers to explore.', 'Fan-made modification/ROM hack.', 'Rosalina and Luma is a creative project that introduces the fan-favorite Mario Galaxy characters into a DS environment, offering custom mechanics and cosmic-themed levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rosario-to-vampire---tanabata-no-miss-youkai-gakuen-japan', 'NDS', 'Rosario to Vampire - Tanabata no Miss Youkai Gakuen (Japan)', '2008', 'Visual Novel', 'Konami', '1', 'Anime Visual Novel', 'Visual Novel / RPG.', 'Navigate the supernatural secrets of Youkai Academy.', 'Anime-based adventure game for Japan.', 'Rosario to Vampire (Japan) features the cast of the popular series. Engage in dialogue-driven story segments and RPG battles as you experience a new tale at the academy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rpg-tkool-ds-japan-ndsi-enhanced', 'NDS', 'RPG Tkool DS (Japan) (NDSi Enhanced)', '2008', 'Development', 'Enterbrain', '1', 'Game Creation Toolkit', 'Creative / RPG.', 'Design and play your own 2D RPG adventures.', 'Powerful RPG creation tool for the DS.', 'RPG Tkool DS (Japan) allows you to create characters, maps, and stories from scratch. Share your creations with others and utilize NDSi features for expanded assets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rub-rabbits!-the-europe-enjafrdeesit', 'NDS', 'Rub Rabbits!, The (Europe) (En,Ja,Fr,De,Es,It)', '2005', 'Action', 'Sega', '1', 'Action Adventure', 'Action / Mini-games.', 'Save the girl through bizarre touch-screen tasks.', 'Sequel to "Project Rub" from SEGA.', 'The Rub Rabbits! (Europe) continues the quirky, artistic style of its predecessor. Use the stylus, mic, and even the GBA slot to complete frantic and funny romantic challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rub-rabbits!-the-usa-enjafrdeesit', 'NDS', 'Rub Rabbits!, The (USA) (En,Ja,Fr,De,Es,It)', '2005', 'Action', 'Sega', '1', 'Action Adventure', 'Action / Mini-games.', 'Save the girl through bizarre touch-screen tasks.', 'North American release of The Rub Rabbits!.', 'Get ready for more weird and wonderful mini-games in The Rub Rabbits! (USA). It features a unique art style, catchy music, and some of the most creative uses of DS hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rubiks-puzzle-world-europe-enfrdeesit', 'NDS', 'Rubik''s Puzzle World (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'EA Bright Light', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Explore a world made of Rubik''s cubes and logic.', 'Cube-themed logic and creation game.', 'Rubik''s Puzzle World (Europe) goes beyond the classic toy. Solve 3D puzzles, build structures, and play mini-games all themed around the world''s most famous cube.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rubiks-world-usa', 'NDS', 'Rubik''s World (USA)', '2008', 'Puzzle', 'GameHouse', '1', 'Logic Puzzle', 'Logic Puzzle.', 'Explore a world made of Rubik''s cubes and logic.', 'North American release of the Rubik''s game.', 'Rubik''s World (USA) offers a variety of brain-teasing modes. From traditional cube solving to innovative physics puzzles, it’s a comprehensive tribute to the Rubik''s brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rudolph---the-red-nosed-reindeer-usa', 'NDS', 'Rudolph - The Red-Nosed Reindeer (USA)', '2010', 'Action', 'Blast! Entertainment', '1', 'Seasonal Platformer', 'Mini-games / Adventure.', 'Help Rudolph and friends save Christmas.', 'Holiday-themed adventure for kids.', 'Rudolph (USA) features classic characters from the stop-motion special. Complete simple puzzles and mini-games to guide Santa’s sleigh through the blizzard and deliver gifts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('runaway---a-twist-of-fate-europe-enfrdeesit', 'NDS', 'Runaway - A Twist of Fate (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Pendulo Studios', '1', 'Point-and-Click Adventure', 'Point & Click Adventure.', 'Solve a dark mystery involving Brian and Gina.', 'The third entry in the acclaimed Runaway saga.', 'Runaway: A Twist of Fate (Europe) brings high-quality 2D art and a mature story to DS. Solve inventory puzzles and navigate a cinematic plot in this definitive portable adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('runaway---the-dream-of-the-turtle-europe-enfrdeesit-rev-1', 'NDS', 'Runaway - The Dream of the Turtle (Europe) (En,Fr,De,Es,It) (Rev 1)', '2006', 'Adventure', 'Pendulo Studios', '1', 'Point-and-Click Adventure', 'Point & Click Adventure.', 'Travel the world to rescue Gina from danger.', 'Second chapter of the Brian Basco adventure.', 'The Dream of the Turtle (Europe) Rev 1 is a refined edition of the classic adventure. Travel from Hawaii to Alaska solving humorous and challenging logic puzzles in a beautiful comic style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('runaway---the-dream-of-the-turtle-europe-enfrde', 'NDS', 'Runaway - The Dream of the Turtle (Europe) (En,Fr,De)', '2006', 'Adventure', 'Pendulo Studios', '1', 'Point-and-Click Adventure', 'Point & Click Adventure.', 'Travel the world to rescue Gina from danger.', 'Multi-language edition (En, Fr, De).', 'This version of Runaway: The Dream of the Turtle (Europe) provides a fully localized experience for major European territories, featuring all the sharp dialogue and brain-teasing inventory gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory---a-fantasy-harvest-moon-europe-enfrdeesit', 'NDS', 'Rune Factory - A Fantasy Harvest Moon (Europe) (En,Fr,De,Es,It)', '2007', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Farm, fight monsters, and get married in Kardia.', 'Fantasy-themed Harvest Moon spin-off.', 'Rune Factory (Europe) blends peaceful crop management with dungeon crawling. Forge weapons, capture monsters as farm help, and build relationships in this innovative genre hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory---a-fantasy-harvest-moon-usa', 'NDS', 'Rune Factory - A Fantasy Harvest Moon (USA)', '2007', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Farm, fight monsters, and get married in Kardia.', 'North American release of the first Rune Factory.', 'Experience "A Fantasy Harvest Moon" in Rune Factory (USA). Master the seasons, clear the local caves of bosses, and find your soulmate in the town of Kardia.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory---shin-bokujou-monogatari-japan', 'NDS', 'Rune Factory - Shin Bokujou Monogatari (Japan)', '2006', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Farm, fight monsters, and get married in Kardia.', 'Original Japanese release of Rune Factory.', 'Rune Factory: Shin Bokujou Monogatari (Japan) launched a legacy. It introduced the "Life Cycle" and "Battle" balance that would define the series for years to come.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory---sinmokjjangiyagi-korea', 'NDS', 'Rune Factory - Sinmokjjangiyagi (Korea)', '2006', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Farm, fight monsters, and get married in Kardia.', 'Korean localized version of the RPG-sim.', 'Enjoy the charming world of Rune Factory in Korea. With fully translated dialogue and tutorials, it’s an accessible and deep simulation experience for Korean players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-2---a-fantasy-harvest-moon-europe-ende', 'NDS', 'Rune Factory 2 - A Fantasy Harvest Moon (Europe) (En,De)', '2008', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Build a legacy and play as your own child.', 'Ambitious sequel with a generational twist.', 'Rune Factory 2 (Europe) features a two-part story. Start as a father building a farm and continue the adventure as your offspring to save the town of Alvarna.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-2---a-fantasy-harvest-moon-usa', 'NDS', 'Rune Factory 2 - A Fantasy Harvest Moon (USA)', '2008', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Build a legacy and play as your own child.', 'North American release of Rune Factory 2.', 'In Rune Factory 2 (USA), the stakes are higher and the farm is bigger. Experience the unique "Second Generation" mechanic that doubles the amount of content and story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-2-japan', 'NDS', 'Rune Factory 2 (Japan)', '2008', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Build a legacy and play as your own child.', 'Original Japanese version of Rune Factory 2.', 'Rune Factory 2 (Japan) expanded the series'' scope. Featuring more monsters, more marriage candidates, and the fan-favorite school system for the second generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-2-japan-rev-1', 'NDS', 'Rune Factory 2 (Japan) (Rev 1)', '2008', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Build a legacy and play as your own child.', 'Revised Japanese edition (Rev 1).', 'This Rev 1 of Rune Factory 2 (Japan) includes technical fixes and balanced game mechanics to ensure a smoother transition between the first and second story arcs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-3---a-fantasy-harvest-moon-usa', 'NDS', 'Rune Factory 3 - A Fantasy Harvest Moon (USA)', '2010', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Transform into a Golden Wooly and save the village.', 'The third and fastest-paced entry on DS.', 'Rune Factory 3 (USA) introduces the transformation mechanic. Battle through dungeons in monster form and enjoy a highly refined farming and social system in Sharance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rune-factory-3-japan', 'NDS', 'Rune Factory 3 (Japan)', '2010', 'RPG', 'Neverland', '1', 'Action RPG / Farming', 'Simulation / Action RPG.', 'Transform into a Golden Wooly and save the village.', 'Original Japanese version of Rune Factory 3.', 'Rune Factory 3 (Japan) is praised for its colorful cast and fluid combat. It represents the pinnacle of the series on the DS hardware with deep customization and AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rupupu-cube---lup-salad-ds-japan', 'NDS', 'Rupupu Cube - Lup Salad DS (Japan)', '2006', 'Puzzle', 'Jupiter', '1', 'Action Puzzle', 'Puzzle / Strategy.', 'Manipulate blocks to clear the salad board.', 'Cult classic Japanese logic puzzle.', 'Rupupu Cube: Lup Salad DS (Japan) is a quirky block-sliding game. Move pieces to match colors and clear the screen in this charming and difficult puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('russel-grants-astrology-europe-enfrdeesit', 'NDS', 'Russel Grant''s Astrology (Europe) (En,Fr,De,Es,It)', '2006', 'Lifestyle', 'Russell Grant', '1', 'Astrology Simulation', 'Lifestyle / Horoscope.', 'Check your daily astrology and birth chart.', 'Astrology and zodiac guide for Europe.', 'Russell Grant''s Astrology (Europe) provides personalized horoscopes and tarot readings. Discover the secrets of the stars and learn about zodiac compatibility in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryoukiki-exercise---riron-no-migite-to-kansei-no-hidarite-japan', 'NDS', 'Ryoukiki Exercise - Riron no Migite to Kansei no Hidarite (Japan)', '2008', 'Educational', 'Benesse', '1', 'Brain Training', 'Brain Training.', 'Balance your left and right brain usage.', 'Cognitive exercise game from Japan.', 'Ryoukiki Exercise focuses on using both hands (and hemispheres). Perform coordination and logic tasks designed to improve your mental flexibility and reaction time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman---dragon-japan', 'NDS', 'Ryuusei no Rockman - Dragon (Japan)', '2006', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Battle cyber-viruses as Mega Man Star Force.', 'First entry of the Star Force saga (Dragon).', 'Ryuusei no Rockman: Dragon (Japan) moves the action to a 3D perspective. Use "Battle Cards" and the "EM Wave World" to protect Earth from alien threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman---leo-japan', 'NDS', 'Ryuusei no Rockman - Leo (Japan)', '2006', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Battle cyber-viruses as Mega Man Star Force.', 'First entry of the Star Force saga (Leo).', 'Choose the Leo version for unique elemental powers and transformations. Battle through a futuristic story and connect with friends via the "BrotherBand" system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman---pegasus-japan', 'NDS', 'Ryuusei no Rockman - Pegasus (Japan)', '2006', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Battle cyber-viruses as Mega Man Star Force.', 'First entry of the Star Force saga (Pegasus).', 'The Pegasus version of Star Force focuses on ice abilities. Collect rare cards and master the new lock-on combat system that redefined Mega Man on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman-2---berserk-x-dinosaur-japan', 'NDS', 'Ryuusei no Rockman 2 - Berserk x Dinosaur (Japan)', '2007', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Master the power of the Berserk and Dinosaur tribes.', 'Dual-version sequel to Star Force.', 'Ryuusei no Rockman 2 (Japan) features the Berserk x Dinosaur crossover. Switch between powerful transformations to defeat the ancient Mu empire in this action RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman-2---berserk-x-shinobi-japan', 'NDS', 'Ryuusei no Rockman 2 - Berserk x Shinobi (Japan)', '2007', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Master the power of the Berserk and Shinobi tribes.', 'Alternative dual-version sequel.', 'Berserk x Shinobi (Japan) offers specialized elemental forms and unique Battle Cards. Navigate the real and wave worlds to uncover the secrets of the lost continent.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman-3---black-ace-japan-rev-1', 'NDS', 'Ryuusei no Rockman 3 - Black Ace (Japan) (Rev 1)', '2009', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Use the Black Ace transformation to delete viruses.', 'The final, definitive Star Force entry (Rev 1).', 'Ryuusei no Rockman 3: Black Ace (Japan) is a high-speed action masterpiece. This revised version includes the latest balancing for competitive wave battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuusei-no-rockman-3---red-joker-japan-rev-1', 'NDS', 'Ryuusei no Rockman 3 - Red Joker (Japan) (Rev 1)', '2009', 'RPG', 'Capcom', '1', 'Action RPG', 'Action RPG.', 'Use the Red Joker transformation to delete viruses.', 'The final, definitive Star Force entry (Rev 1).', 'Red Joker (Japan) focuses on heavy firepower and defense. With over 400 Battle Cards and an epic conclusion, it’s a must-play for Mega Man fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saeki-chizu-shiki-yumemihada---dream-skincare-japan', 'NDS', 'Saeki Chizu Shiki Yumemihada - Dream Skincare (Japan)', '2008', 'Lifestyle', 'Shiseido', '1', 'Beauty Simulation', 'Lifestyle / Beauty.', 'Follow a professional skincare routine.', 'Digital skincare guide and diary for Japan.', 'Saeki Chizu Shiki Yumemihada (Japan) features advice from the famous beauty expert. Track your daily habits and learn professional massage techniques for healthier skin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('safari-adventures---africa-europe-enfrdeesitnl', 'NDS', 'Safari Adventures - Africa (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Adventure', 'Destineer', '1', 'Educational Adventure', 'Action / Photography.', 'Photograph the "Big Five" in the African savanna.', 'Nature exploration and photography sim.', 'Safari Adventures: Africa (Europe) lets you explore the wilderness in a jeep. Take the best shots of lions and elephants to complete your field guide in six languages.');
