INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('safecracker---the-ultimate-puzzle-adventure-europe-enfrdeesit', 'NDS', 'Safecracker - The Ultimate Puzzle Adventure (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Kheops Studio', '1', 'Logic Puzzle Adventure', 'Logic Puzzle.', 'Crack the code and open the world''s most secure safes.', 'First-person puzzle adventure for Europe.', 'Safecracker (Europe) challenges you with 35 unique safes. Solve mechanical and logical puzzles in a lavish mansion to claim your inheritance in this multi-language hit.');
