INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saga-2---hihou-densetsu---goddess-of-destiny-japan', 'NDS', 'SaGa 2 - Hihou Densetsu - Goddess of Destiny (Japan)', '2009', 'RPG', 'Square Enix', '1', 'Turn-Based RPG', 'JRPG.', 'Travel the worlds to find the 77 relics of the gods.', 'Full 3D remake of the Game Boy classic.', 'SaGa 2: Goddess of Destiny (Japan) is a stunning remake with a revamped combat system. Manage a party of humans, mutants, and robots in an epic journey across dimensions.');
