INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sankei-sports-kanshuu---wi-fi-baken-yosou-ryoku-training---umania-2007-nendo-ban-japan', 'NDS', 'Sankei Sports Kanshuu - Wi-Fi Baken Yosou Ryoku Training - Umania 2007 Nendo Ban (Japan)', '2007', 'Gambling Training', 'Sankei Sports', '1', 'Horse Racing Prediction', 'Sports / Betting.', 'Train your prediction skills with Wi-Fi updates.', 'Horse racing training tool with 2007 season data.', 'Umania 2007 (Japan) allows you to use Wi-Fi to stay updated with real-world racing results. Practice your betting strategies based on authentic data from Sankei Sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sansuu-olympic-iinkai-kouan---suuji-de-kitaeru-nouryoku-training---algo-&-trinca-japan', 'NDS', 'Sansuu Olympic Iinkai Kouan - Suuji de Kitaeru Nouryoku Training - Algo & Trinca (Japan)', '2008', 'Educational', 'Benesse', '1', 'Math Training', 'Logic Puzzle / Math.', 'Improve your brain power with the "Algo" method.', 'Mathematics and logic training based on the Olympic method.', 'Algo & Trinca (Japan) features competitive number puzzles. Sharpen your mental math and logical deduction skills through structured, Olympic-level challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sansuu-puzzle-de-migaku---gakken-otona-no-shikou-sense-japan', 'NDS', 'Sansuu Puzzle de Migaku - Gakken Otona no Shikou Sense (Japan)', '2009', 'Educational', 'Gakken', '1', 'Logic Puzzle', 'Logic Puzzle / Math.', 'Develop your "thinking sense" with adult math puzzles.', 'Advanced mathematics puzzle collection for Japan.', 'Sansuu Puzzle de Migaku (Japan) is designed for adults. It offers complex logic and arithmetic problems that require creative thinking and deep focus to solve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sansuu-puzzle-game---equal-card-ds-japan', 'NDS', 'Sansuu Puzzle Game - Equal Card DS (Japan)', '2007', 'Puzzle', 'Jupiter', '1', 'Math Puzzle', 'Card Game / Math.', 'Use math to make equations equal with cards.', 'Educational math card game for Japan.', 'Equal Card DS (Japan) challenges you to reach target numbers using basic arithmetic. It’s a fun, fast-paced way to practice mental calculation using a deck of cards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('santa-claus-is-comin-to-town-usa', 'NDS', 'Santa Claus is Comin'' to Town (USA)', '2008', 'Adventure', 'Crave Entertainment', '1', 'Family Adventure', 'Action / Platformer.', 'Help Santa deliver toys and save the holiday.', 'Christmas-themed adventure based on the classic special.', 'Santa Claus is Comin'' to Town (USA) features 2D platforming action. Navigate through the North Pole and evade the Winter Warlock to ensure every child gets their gift.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sarah---die-hueterin-des-einhorns-europe-frde', 'NDS', 'Sarah - Die Hueterin des Einhorns (Europe) (Fr,De)', '2009', 'Adventure', 'Teyon', '1', 'Fantasy Adventure', 'Adventure / Fantasy.', 'Save the forest and protect the last unicorn.', 'Magical adventure for French and German speakers.', 'Sarah: Die Hueterin des Einhorns (Europe) follows a young girl''s quest. Solve puzzles and explore a fairy-tale world to safeguard a mythical creature from dark forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sarah---keeper-of-the-unicorn-usa-enes', 'NDS', 'Sarah - Keeper of the Unicorn (USA) (En,Es)', '2009', 'Adventure', 'Teyon', '1', 'Fantasy Adventure', 'Adventure / Fantasy.', 'Save the forest and protect the last unicorn.', 'North American release of the unicorn quest.', 'Embark on a magical journey in Sarah: Keeper of the Unicorn (USA). Featuring beautiful environments and a heartwarming story, it''s an ideal adventure for fans of fantasy and nature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sarainneun-yeongeoro-ganghaejineun-siljeon!---ds-yeongeo-sammaegyeong-korea', 'NDS', 'Sarainneun Yeongeoro Ganghaejineun Siljeon! - DS Yeongeo Sammaegyeong (Korea)', '2008', 'Educational', 'Daewon Media', '1', 'English Training', 'Educational / Language.', 'Improve your English through practical conversation.', 'Immersive English language trainer for Korea.', 'DS Yeongeo Sammaegyeong (Korea) uses the DS microphone and touch screen to teach real-world English. Practice speaking and listening through interactive scenarios and daily drills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saru-saru-ds-japan', 'NDS', 'Saru Saru DS (Japan)', '2006', 'Action', 'Sega', '1', 'Action Arcade', 'Life simulation.', 'Guide a tribe of monkeys through evolution.', 'Unique monkey evolution simulator for Japan.', 'Saru Saru DS (Japan) puts you in charge of a primitive monkey tribe. Manage their food, safety, and social interactions to help them evolve and survive in a prehistoric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('satisfashion---rock-the-runway-usa', 'NDS', 'Satisfashion - Rock the Runway (USA)', '2009', 'Simulation', 'Destineer', '1', 'Fashion Simulation', 'Fashion / Rhythm.', 'Design outfits and dominate the runway.', 'Fashion competition game for the USA.', 'Satisfashion: Rock the Runway (USA) combines creative design with rhythm-based fashion shows. Choose fabrics, cut patterns, and strut the catwalk to become a fashion icon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sawaru-made-in-wario-japan', 'NDS', 'Sawaru Made in Wario (Japan)', '2004', 'Party', 'Nintendo', '1', 'Microgame Collection', 'Mini-games.', 'Complete hundreds of micro-games in seconds.', 'The Japanese version of WarioWare: Touched!.', 'Sawaru Made in Wario (Japan) utilizes the touch screen and microphone for frantic, seconds-long challenges. It’s a chaotic and hilarious showcase of the DS hardware capabilities.');
