INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sbi-group-kanshuu---hajimeyou!-shisan-unyou-ds-japan', 'NDS', 'SBI Group Kanshuu - Hajimeyou! Shisan Unyou DS (Japan)', '2007', 'Simulation', 'SBI Group', '1', 'Finance Simulation', 'Educational / Finance.', 'Learn the basics of asset management and investing.', 'Financial planning and investment guide for Japan.', 'SBI Group Kanshuu (Japan) is a practical tool for learning about stocks, bonds, and personal finance. Use interactive lessons and simulations to grow your virtual portfolio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sbk---snowboard-kids-europe-enfrde', 'NDS', 'SBK - Snowboard Kids (Europe) (En,Fr,De)', '2005', 'Sports', 'Racjin', '4', 'Snowboarding', 'Racing / Sports.', 'Race down snowy slopes and use wacky items.', 'Reimagined snowboard racing for Europe.', 'SBK: Snowboard Kids (Europe) brings the classic N64 spirit to DS. Use power-ups, perform tricks, and outpace your rivals in stylized, high-speed downhill competitions.');
