INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scene-it-twilight-europe-enfrdeesit', 'NDS', 'Scene It Twilight (Europe) (En,Fr,De,Es,It)', '2009', 'Trivia', 'Screenlife', '4', 'Movie Trivia', 'Trivia / Party.', 'Prove you are the ultimate Twilight fan.', 'Movie-themed trivia game for the European market.', 'Scene It? Twilight (Europe) features clips and images from the film saga. Challenge your friends in multi-language trivia rounds to see who knows the most about Bella and Edward.');
