INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('schatz-der-delfine-der-europe-enfrdeesit', 'NDS', 'Schatz der Delfine, Der (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Deep Silver', '1', 'Educational Adventure', 'Adventure / Nature.', 'Explore the ocean and protect the dolphins.', 'Underwater adventure and environmental game.', 'Schatz der Delfine (Europe) takes you beneath the waves. Interact with marine life, solve environmental puzzles, and discover hidden treasures in the deep blue sea.');
