INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scribblenauts-europe-enfrdeesitnl', 'NDS', 'Scribblenauts (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Action / Puzzle', '5th Cell', '1', 'Creative Puzzle', 'Puzzle / Sandbox.', 'Write any word to summon objects and solve puzzles.', 'Groundbreaking "write anything" puzzle game.', 'Scribblenauts (Europe) lets your imagination run wild. Type the name of any object to bring it to life and collect Starites in this multilingual creative masterpiece.');
