INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sillybandz-ds-usa-enfres', 'NDS', 'Sillybandz DS (USA) (En,Fr,Es)', '2012', 'Party', 'Flashman Studios', '4', 'Collectible Party', 'Puzzle / Strategy.', 'Rescue lost Silly Bandz and collect them all.', 'Game based on the shaped rubber band craze.', 'Sillybandz DS (USA) features physics-based puzzles. Use the stylus to aim and shoot bands to free your collection, featuring various themes like animals and fantasy shapes.');
